#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

static
void kernel_2mm(int ni, int nj, int nk, int nl,
		DATA_TYPE alpha,
		DATA_TYPE beta,
		DATA_TYPE POLYBENCH_2D(tmp,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j, k;

#pragma scop

#if defined(__riscv_vector)

  for (i = 0; i < _PB_NI; i++) {
    DATA_TYPE *tmp_i = &tmp[i][0];
    for (j = 0; j < _PB_NJ; ) {
      size_t vl;
      DATA_TYPE *tmp_ij = &tmp_i[j];
#if defined(DATA_TYPE_IS_DOUBLE)
      vl = __riscv_vsetvl_e64m1((size_t)(_PB_NJ - j));
      vfloat64m1_t vacc = __riscv_vfmv_v_f_f64m1((double)0.0, vl);
      for (k = 0; k < _PB_NK; ++k) {
        vfloat64m1_t vb = __riscv_vle64_v_f64m1(&B[k][j], vl);
        double a = (double)(alpha * A[i][k]);
        vacc = __riscv_vfmacc_vf_f64m1(vacc, a, vb, vl);
      }
      __riscv_vse64_v_f64m1(tmp_ij, vacc, vl);
#elif defined(DATA_TYPE_IS_FLOAT)
      vl = __riscv_vsetvl_e32m1((size_t)(_PB_NJ - j));
      vfloat32m1_t vacc = __riscv_vfmv_v_f_f32m1((float)0.0f, vl);
      for (k = 0; k < _PB_NK; ++k) {
        vfloat32m1_t vb = __riscv_vle32_v_f32m1(&B[k][j], vl);
        float a = (float)(alpha * A[i][k]);
        vacc = __riscv_vfmacc_vf_f32m1(vacc, a, vb, vl);
      }
      __riscv_vse32_v_f32m1(tmp_ij, vacc, vl);
#else
      vl = 1;
      tmp[i][j] = SCALAR_VAL(0.0);
      for (k = 0; k < _PB_NK; ++k)
        tmp[i][j] += alpha * A[i][k] * B[k][j];
#endif
      j += (int)vl;
    }
  }

  for (i = 0; i < _PB_NI; i++) {
    DATA_TYPE *tmp_i = &tmp[i][0];
    DATA_TYPE *D_i = &D[i][0];
    for (j = 0; j < _PB_NL; ) {
      size_t vl;
#if defined(DATA_TYPE_IS_DOUBLE)
      vl = __riscv_vsetvl_e64m1((size_t)(_PB_NL - j));
      vfloat64m1_t vd = __riscv_vle64_v_f64m1(&D_i[j], vl);
      vd = __riscv_vfmul_vf_f64m1(vd, (double)beta, vl);
      for (k = 0; k < _PB_NJ; ++k) {
        vfloat64m1_t vc = __riscv_vle64_v_f64m1(&C[k][j], vl);
        double t = (double)tmp_i[k];
        vd = __riscv_vfmacc_vf_f64m1(vd, t, vc, vl);
      }
      __riscv_vse64_v_f64m1(&D_i[j], vd, vl);
#elif defined(DATA_TYPE_IS_FLOAT)
      vl = __riscv_vsetvl_e32m1((size_t)(_PB_NL - j));
      vfloat32m1_t vd = __riscv_vle32_v_f32m1(&D_i[j], vl);
      vd = __riscv_vfmul_vf_f32m1(vd, (float)beta, vl);
      for (k = 0; k < _PB_NJ; ++k) {
        vfloat32m1_t vc = __riscv_vle32_v_f32m1(&C[k][j], vl);
        float t = (float)tmp_i[k];
        vd = __riscv_vfmacc_vf_f32m1(vd, t, vc, vl);
      }
      __riscv_vse32_v_f32m1(&D_i[j], vd, vl);
#else
      vl = 1;
      D[i][j] *= beta;
      for (k = 0; k < _PB_NJ; ++k)
        D[i][j] += tmp[i][k] * C[k][j];
#endif
      j += (int)vl;
    }
  }

#else

  for (i = 0; i < _PB_NI; i++)
    for (j = 0; j < _PB_NJ; j++)
      {
	tmp[i][j] = SCALAR_VAL(0.0);
	for (k = 0; k < _PB_NK; ++k)
	  tmp[i][j] += alpha * A[i][k] * B[k][j];
      }
  for (i = 0; i < _PB_NI; i++)
    for (j = 0; j < _PB_NL; j++)
      {
	D[i][j] *= beta;
	for (k = 0; k < _PB_NJ; ++k)
	  D[i][j] += tmp[i][k] * C[k][j];
      }

#endif

#pragma endscop

}

