static
void kernel_3mm(int ni, int nj, int nk, int nl, int nm,
		DATA_TYPE POLYBENCH_2D(E,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(F,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(C,NJ,NM,nj,nm),
		DATA_TYPE POLYBENCH_2D(D,NM,NL,nm,nl),
		DATA_TYPE POLYBENCH_2D(G,NI,NL,ni,nl))
{
  int i, j, k;

#pragma scop

#if defined(__riscv_vector)

  for (i = 0; i < _PB_NI; i++) {
    DATA_TYPE * __restrict__ Ei = &E[i][0];
    DATA_TYPE * __restrict__ Ai = &A[i][0];
    for (j = 0; j < _PB_NJ; ) {
      size_t rem = (size_t)(_PB_NJ - j);
      size_t vl = __riscv_vsetvl_e64m1(rem);
      vfloat64m1_t acc = __riscv_vfmv_v_f_f64m1(0.0, vl);
      for (k = 0; k < _PB_NK; ++k) {
        vfloat64m1_t vb = __riscv_vle64_v_f64m1(&B[k][j], vl);
        acc = __riscv_vfmacc_vf_f64m1(acc, Ai[k], vb, vl);
      }
      __riscv_vse64_v_f64m1(&Ei[j], acc, vl);
      j += (int)vl;
    }
  }

  for (i = 0; i < _PB_NJ; i++) {
    DATA_TYPE * __restrict__ Fi = &F[i][0];
    DATA_TYPE * __restrict__ Ci = &C[i][0];
    for (j = 0; j < _PB_NL; ) {
      size_t rem = (size_t)(_PB_NL - j);
      size_t vl = __riscv_vsetvl_e64m1(rem);
      vfloat64m1_t acc = __riscv_vfmv_v_f_f64m1(0.0, vl);
      for (k = 0; k < _PB_NM; ++k) {
        vfloat64m1_t vd = __riscv_vle64_v_f64m1(&D[k][j], vl);
        acc = __riscv_vfmacc_vf_f64m1(acc, Ci[k], vd, vl);
      }
      __riscv_vse64_v_f64m1(&Fi[j], acc, vl);
      j += (int)vl;
    }
  }

  for (i = 0; i < _PB_NI; i++) {
    DATA_TYPE * __restrict__ Gi = &G[i][0];
    DATA_TYPE * __restrict__ Ei = &E[i][0];
    for (j = 0; j < _PB_NL; ) {
      size_t rem = (size_t)(_PB_NL - j);
      size_t vl = __riscv_vsetvl_e64m1(rem);
      vfloat64m1_t acc0 = __riscv_vfmv_v_f_f64m1(0.0, vl);
      vfloat64m1_t acc1 = __riscv_vfmv_v_f_f64m1(0.0, vl);
      vfloat64m1_t acc2 = __riscv_vfmv_v_f_f64m1(0.0, vl);
      vfloat64m1_t acc3 = __riscv_vfmv_v_f_f64m1(0.0, vl);

      for (k = 0; k + 3 < _PB_NJ; k += 4) {
        vfloat64m1_t vf0 = __riscv_vle64_v_f64m1(&F[k    ][j], vl);
        vfloat64m1_t vf1 = __riscv_vle64_v_f64m1(&F[k + 1][j], vl);
        vfloat64m1_t vf2 = __riscv_vle64_v_f64m1(&F[k + 2][j], vl);
        vfloat64m1_t vf3 = __riscv_vle64_v_f64m1(&F[k + 3][j], vl);
        acc0 = __riscv_vfmacc_vf_f64m1(acc0, Ei[k    ], vf0, vl);
        acc1 = __riscv_vfmacc_vf_f64m1(acc1, Ei[k + 1], vf1, vl);
        acc2 = __riscv_vfmacc_vf_f64m1(acc2, Ei[k + 2], vf2, vl);
        acc3 = __riscv_vfmacc_vf_f64m1(acc3, Ei[k + 3], vf3, vl);
      }

      acc0 = __riscv_vfadd_vv_f64m1(acc0, acc1, vl);
      acc2 = __riscv_vfadd_vv_f64m1(acc2, acc3, vl);
      acc0 = __riscv_vfadd_vv_f64m1(acc0, acc2, vl);

      for (; k < _PB_NJ; ++k) {
        vfloat64m1_t vf = __riscv_vle64_v_f64m1(&F[k][j], vl);
        acc0 = __riscv_vfmacc_vf_f64m1(acc0, Ei[k], vf, vl);
      }

      __riscv_vse64_v_f64m1(&Gi[j], acc0, vl);
      j += (int)vl;
    }
  }

#else

  for (i = 0; i < _PB_NI; i++)
    for (j = 0; j < _PB_NJ; j++)
      {
	E[i][j] = SCALAR_VAL(0.0);
	for (k = 0; k < _PB_NK; ++k)
	  E[i][j] += A[i][k] * B[k][j];
      }

  for (i = 0; i < _PB_NJ; i++)
    for (j = 0; j < _PB_NL; j++)
      {
	F[i][j] = SCALAR_VAL(0.0);
	for (k = 0; k < _PB_NM; ++k)
	  F[i][j] += C[i][k] * D[k][j];
      }

  for (i = 0; i < _PB_NI; i++)
    for (j = 0; j < _PB_NL; j++)
      {
	G[i][j] = SCALAR_VAL(0.0);
	for (k = 0; k < _PB_NJ; ++k)
	  G[i][j] += E[i][k] * F[k][j];
      }

#endif

#pragma endscop

}

