static
void kernel_adi(int tsteps, int n,
		DATA_TYPE POLYBENCH_2D(u,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(v,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(p,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(q,N,N,n,n))
{
  int t, i, j;
  DATA_TYPE DX, DY, DT;
  DATA_TYPE B1, B2;
  DATA_TYPE mul1, mul2;
  DATA_TYPE a, b, c, d, e, f;

#pragma scop

  DX = SCALAR_VAL(1.0)/(DATA_TYPE)_PB_N;
  DY = SCALAR_VAL(1.0)/(DATA_TYPE)_PB_N;
  DT = SCALAR_VAL(1.0)/(DATA_TYPE)_PB_TSTEPS;
  B1 = SCALAR_VAL(2.0);
  B2 = SCALAR_VAL(1.0);
  mul1 = B1 * DT / (DX * DX);
  mul2 = B2 * DT / (DY * DY);

  a = -mul1 /  SCALAR_VAL(2.0);
  b = SCALAR_VAL(1.0)+mul1;
  c = a;
  d = -mul2 / SCALAR_VAL(2.0);
  e = SCALAR_VAL(1.0)+mul2;
  f = d;

  {
    const DATA_TYPE one = SCALAR_VAL(1.0);
    const DATA_TYPE two = SCALAR_VAL(2.0);
    const DATA_TYPE coeff_u_center = one + two * d;
    const DATA_TYPE coeff_v_center = one + two * a;

    for (t = 1; t <= _PB_TSTEPS; t++) {

      for (i = 1; i < _PB_N - 1; i++) {
        v[0][i] = one;
        p[i][0] = SCALAR_VAL(0.0);
        q[i][0] = v[0][i];

        {
          DATA_TYPE p_prev = p[i][0];
          DATA_TYPE q_prev = q[i][0];
          for (j = 1; j < _PB_N - 1; j++) {
            DATA_TYPE denom = a * p_prev + b;
            DATA_TYPE p_cur = -c / denom;
            DATA_TYPE q_cur =
              (-d * u[j][i-1]
               + coeff_u_center * u[j][i]
               - f * u[j][i+1]
               - a * q_prev) / denom;
            p[i][j] = p_cur;
            q[i][j] = q_cur;
            p_prev = p_cur;
            q_prev = q_cur;
          }
        }

        v[_PB_N-1][i] = one;
        for (j = _PB_N - 2; j >= 1; j--) {
          v[j][i] = p[i][j] * v[j+1][i] + q[i][j];
        }
      }

      for (i = 1; i < _PB_N - 1; i++) {
        u[i][0] = one;
        p[i][0] = SCALAR_VAL(0.0);
        q[i][0] = u[i][0];

        {
          DATA_TYPE p_prev = p[i][0];
          DATA_TYPE q_prev = q[i][0];
          DATA_TYPE *restrict pi = &p[i][0];
          DATA_TYPE *restrict qi = &q[i][0];
          DATA_TYPE *restrict vim1 = &v[i-1][0];
          DATA_TYPE *restrict vi   = &v[i][0];
          DATA_TYPE *restrict vip1 = &v[i+1][0];

          for (j = 1; j < _PB_N - 1; j++) {
            DATA_TYPE denom = d * p_prev + e;
            DATA_TYPE p_cur = -f / denom;
            DATA_TYPE q_cur =
              (-a * vim1[j]
               + coeff_v_center * vi[j]
               - c * vip1[j]
               - d * q_prev) / denom;
            pi[j] = p_cur;
            qi[j] = q_cur;
            p_prev = p_cur;
            q_prev = q_cur;
          }
        }

        u[i][_PB_N-1] = one;
        {
          DATA_TYPE *restrict ui = &u[i][0];
          DATA_TYPE *restrict pi = &p[i][0];
          DATA_TYPE *restrict qi = &q[i][0];
          DATA_TYPE next = ui[_PB_N-1];
          for (j = _PB_N - 2; j >= 1; j--) {
            DATA_TYPE cur = pi[j] * next + qi[j];
            ui[j] = cur;
            next = cur;
          }
        }
      }
    }
  }

#pragma endscop
}

