static
void kernel_atax(int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(tmp,M,m))
{
  int i, j;

#pragma scop
#if defined(__riscv_vector)

  for (i = 0; i < _PB_N; )
    {
      size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - i));
      vfloat64m1_t vy0 = __riscv_vfmv_v_f_f64m1(0.0, vl);
      __riscv_vse64_v_f64m1(&y[i], vy0, vl);
      i += (int)vl;
    }

  for (i = 0; i < _PB_M; i++)
    {
      DATA_TYPE sum = SCALAR_VAL(0.0);
      DATA_TYPE *Ai = &A[i][0];

      {
        size_t vlmax = __riscv_vsetvlmax_e64m1();
        vfloat64m1_t vacc = __riscv_vfmv_v_f_f64m1(0.0, vlmax);

        for (j = 0; j < _PB_N; )
          {
            size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - j));
            vfloat64m1_t va = __riscv_vle64_v_f64m1(&Ai[j], vl);
            vfloat64m1_t vx = __riscv_vle64_v_f64m1(&x[j], vl);
            vacc = __riscv_vfmacc_vv_f64m1(vacc, va, vx, vl);
            j += (int)vl;
          }

        {
          vfloat64m1_t vzero = __riscv_vfmv_v_f_f64m1(0.0, vlmax);
          vfloat64m1_t vred = __riscv_vfredusum_vs_f64m1_f64m1(vacc, vzero, vlmax);
          sum = __riscv_vfmv_f_s_f64m1_f64(vred);
        }
      }

      tmp[i] = sum;

      for (j = 0; j < _PB_N; )
        {
          size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - j));
          vfloat64m1_t va = __riscv_vle64_v_f64m1(&Ai[j], vl);
          vfloat64m1_t vy = __riscv_vle64_v_f64m1(&y[j], vl);
          vy = __riscv_vfmacc_vf_f64m1(vy, sum, va, vl);
          __riscv_vse64_v_f64m1(&y[j], vy, vl);
          j += (int)vl;
        }
    }

#else

  for (i = 0; i < _PB_N; i++)
    y[i] = 0;
  for (i = 0; i < _PB_M; i++)
    {
      tmp[i] = SCALAR_VAL(0.0);
      for (j = 0; j < _PB_N; j++)
	tmp[i] = tmp[i] + A[i][j] * x[j];
      for (j = 0; j < _PB_N; j++)
	y[j] = y[j] + A[i][j] * tmp[i];
    }

#endif
#pragma endscop

}

