static
void kernel_bicg(int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		 DATA_TYPE POLYBENCH_1D(s,M,m),
		 DATA_TYPE POLYBENCH_1D(q,N,n),
		 DATA_TYPE POLYBENCH_1D(p,M,m),
		 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_M; i++)
    s[i] = 0;

#if defined(__riscv_vector) && defined(DATA_TYPE_IS_FLOAT)
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE qi = SCALAR_VAL(0.0);
      DATA_TYPE ri = r[i];
      size_t jv = 0;

      for (; jv < (size_t)_PB_M; )
        {
          size_t vl = __riscv_vsetvl_e32m1((size_t)_PB_M - jv);
          vfloat32m1_t va = __riscv_vle32_v_f32m1(&A[i][jv], vl);
          vfloat32m1_t vs = __riscv_vle32_v_f32m1(&s[jv], vl);
          vfloat32m1_t vp = __riscv_vle32_v_f32m1(&p[jv], vl);
          vfloat32m1_t vprod = __riscv_vfmul_vv_f32m1(va, vp, vl);

          vs = __riscv_vfmacc_vf_f32m1(vs, ri, va, vl);
          __riscv_vse32_v_f32m1(&s[jv], vs, vl);

          qi += __riscv_vfmv_f_s_f32m1_f32(
                  __riscv_vfredusum_vs_f32m1_f32m1(
                    vprod,
                    __riscv_vfmv_s_f_f32m1(SCALAR_VAL(0.0), vl),
                    vl));
          jv += vl;
        }

      q[i] = qi;
    }

#elif defined(__riscv_vector) && defined(DATA_TYPE_IS_DOUBLE)
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE qi = SCALAR_VAL(0.0);
      DATA_TYPE ri = r[i];
      size_t jv = 0;

      for (; jv < (size_t)_PB_M; )
        {
          size_t vl = __riscv_vsetvl_e64m1((size_t)_PB_M - jv);
          vfloat64m1_t va = __riscv_vle64_v_f64m1(&A[i][jv], vl);
          vfloat64m1_t vs = __riscv_vle64_v_f64m1(&s[jv], vl);
          vfloat64m1_t vp = __riscv_vle64_v_f64m1(&p[jv], vl);
          vfloat64m1_t vprod = __riscv_vfmul_vv_f64m1(va, vp, vl);

          vs = __riscv_vfmacc_vf_f64m1(vs, ri, va, vl);
          __riscv_vse64_v_f64m1(&s[jv], vs, vl);

          qi += __riscv_vfmv_f_s_f64m1_f64(
                  __riscv_vfredusum_vs_f64m1_f64m1(
                    vprod,
                    __riscv_vfmv_s_f_f64m1(SCALAR_VAL(0.0), vl),
                    vl));
          jv += vl;
        }

      q[i] = qi;
    }

#else
  for (i = 0; i < _PB_N; i++)
    {
      q[i] = SCALAR_VAL(0.0);
      for (j = 0; j < _PB_M; j++)
	{
	  s[j] = s[j] + r[i] * A[i][j];
	  q[i] = q[i] + A[i][j] * p[j];
	}
    }
#endif
#pragma endscop

}

