static
void kernel_cholesky(int n,
		     DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *Ai = A[i];

    for (j = 0; j < i; j++) {
      DATA_TYPE *Aj = A[j];
      DATA_TYPE sum = Ai[j];

#if defined(__riscv_vector) && defined(DATA_TYPE_IS_DOUBLE)
      k = 0;
      {
        size_t vl;
        vfloat64m1_t vacc = __riscv_vfmv_v_f_f64m1(0.0, 1);
        for (; k < j; k += (int)vl) {
          vl = __riscv_vsetvl_e64m1((size_t)(j - k));
          vfloat64m1_t vai = __riscv_vle64_v_f64m1(&Ai[k], vl);
          vfloat64m1_t vaj = __riscv_vle64_v_f64m1(&Aj[k], vl);
          vacc = __riscv_vfmacc_vv_f64m1(vacc, vai, vaj, vl);
        }
        sum -= __riscv_vfmv_f_s_f64m1_f64(
            __riscv_vfredusum_vs_f64m1_f64m1(
                vacc,
                __riscv_vfmv_v_f_f64m1(0.0, 1),
                1));
      }
      for (; k < j; k++) {
