      k = 0;
      {
        size_t vl;
        vfloat32m1_t vacc = __riscv_vfmv_v_f_f32m1(0.0f, 1);
        for (; k < j; k += (int)vl) {
          vl = __riscv_vsetvl_e32m1((size_t)(j - k));
          vfloat32m1_t vai = __riscv_vle32_v_f32m1(&Ai[k], vl);
          vfloat32m1_t vaj = __riscv_vle32_v_f32m1(&Aj[k], vl);
          vacc = __riscv_vfmacc_vv_f32m1(vacc, vai, vaj, vl);
        }
        sum -= __riscv_vfmv_f_s_f32m1_f32(
            __riscv_vfredusum_vs_f32m1_f32m1(
                vacc,
                __riscv_vfmv_v_f_f32m1(0.0f, 1),
                1));
      }
      for (; k < j; k++) {
        sum -= Ai[k] * Aj[k];
      }
#else
      for (k = 0; k < j; k++) {
        sum -= Ai[k] * Aj[k];
      }
#endif

      Ai[j] = sum / Aj[j];
    }

    {
      DATA_TYPE sum = Ai[i];

#if defined(__riscv_vector) && defined(DATA_TYPE_IS_DOUBLE)
      k = 0;
      {
        size_t vl;
        vfloat64m1_t vacc = __riscv_vfmv_v_f_f64m1(0.0, 1);
        for (; k < i; k += (int)vl) {
          vl = __riscv_vsetvl_e64m1((size_t)(i - k));
          vfloat64m1_t vai = __riscv_vle64_v_f64m1(&Ai[k], vl);
          vacc = __riscv_vfmacc_vv_f64m1(vacc, vai, vai, vl);
        }
        sum -= __riscv_vfmv_f_s_f64m1_f64(
            __riscv_vfredusum_vs_f64m1_f64m1(
                vacc,
                __riscv_vfmv_v_f_f64m1(0.0, 1),
                1));
      }
      for (; k < i; k++) {
        sum -= Ai[k] * Ai[k];
      }
#elif defined(__riscv_vector)
      k = 0;
      {
        size_t vl;
        vfloat32m1_t vacc = __riscv_vfmv_v_f_f32m1(0.0f, 1);
        for (; k < i; k += (int)vl) {
          vl = __riscv_vsetvl_e32m1((size_t)(i - k));
          vfloat32m1_t vai = __riscv_vle32_v_f32m1(&Ai[k], vl);
          vacc = __riscv_vfmacc_vv_f32m1(vacc, vai, vai, vl);
        }
        sum -= __riscv_vfmv_f_s_f32m1_f32(
            __riscv_vfredusum_vs_f32m1_f32m1(
                vacc,
                __riscv_vfmv_v_f_f32m1(0.0f, 1),
                1));
