static
void kernel_correlation(int m, int n,
			DATA_TYPE float_n,
			DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
			DATA_TYPE POLYBENCH_2D(corr,M,M,m,m),
			DATA_TYPE POLYBENCH_1D(mean,M,m),
			DATA_TYPE POLYBENCH_1D(stddev,M,m))
{
  int i, j, k;
  DATA_TYPE eps = SCALAR_VAL(0.1);

#pragma scop
  for (j = 0; j < _PB_M; j++)
  {
    DATA_TYPE sum = SCALAR_VAL(0.0);
    for (i = 0; i < _PB_N; i++)
      sum += data[i][j];
    mean[j] = sum / float_n;
  }

  for (j = 0; j < _PB_M; j++)
  {
    DATA_TYPE sum = SCALAR_VAL(0.0);
    DATA_TYPE mj = mean[j];
    for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE d = data[i][j] - mj;
      sum += d * d;
    }
    stddev[j] = sum / float_n;
    stddev[j] = SQRT_FUN(stddev[j]);
    stddev[j] = stddev[j] <= eps ? SCALAR_VAL(1.0) : stddev[j];
  }

  {
    DATA_TYPE sqrt_float_n = SQRT_FUN(float_n);
    for (i = 0; i < _PB_N; i++)
    {
#if defined(__riscv_vector)
      int jj = 0;
      for (; jj < _PB_M; )
      {
        size_t vl = __riscv_vsetvl_e64m1(_PB_M - jj);
        vfloat64m1_t vdata = __riscv_vle64_v_f64m1(&data[i][jj], vl);
        vfloat64m1_t vmean = __riscv_vle64_v_f64m1(&mean[jj], vl);
        vfloat64m1_t vstd = __riscv_vle64_v_f64m1(&stddev[jj], vl);
        vfloat64m1_t vnum = __riscv_vfsub_vv_f64m1(vdata, vmean, vl);
        vfloat64m1_t vscale = __riscv_vfmul_vf_f64m1(vstd, sqrt_float_n, vl);
        vfloat64m1_t vout = __riscv_vfdiv_vv_f64m1(vnum, vscale, vl);
        __riscv_vse64_v_f64m1(&data[i][jj], vout, vl);
        jj += (int)vl;
      }
#else
      for (j = 0; j < _PB_M; j++)
      {
        data[i][j] -= mean[j];
        data[i][j] /= sqrt_float_n * stddev[j];
      }
#endif
    }
  }

  for (i = 0; i < _PB_M - 1; i++)
  {
    corr[i][i] = SCALAR_VAL(1.0);
    for (j = i + 1; j < _PB_M; j++)
    {
      DATA_TYPE sum = SCALAR_VAL(0.0);
#if defined(__riscv_vector)
      k = 0;
      if (_PB_N >= 2)
      {
        ptrdiff_t stride = (ptrdiff_t)(m * sizeof(DATA_TYPE));
        for (; k + 1 < _PB_N; )
        {
          size_t rem = (size_t)(_PB_N - k);
          size_t vl = __riscv_vsetvl_e64m1(rem > 2 ? rem >> 1 : 1);
          vfloat64m1_t vi0 = __riscv_vlse64_v_f64m1(&data[k][i], stride, vl);
          vfloat64m1_t vj0 = __riscv_vlse64_v_f64m1(&data[k][j], stride, vl);
          vfloat64m1_t vi1 = __riscv_vlse64_v_f64m1(&data[k + (int)vl][i], stride, vl);
          vfloat64m1_t vj1 = __riscv_vlse64_v_f64m1(&data[k + (int)vl][j], stride, vl);
          vfloat64m1_t vacc = __riscv_vfmul_vv_f64m1(vi0, vj0, vl);
          vacc = __riscv_vfmacc_vv_f64m1(vacc, vi1, vj1, vl);
          vfloat64m1_t vred = __riscv_vfredusum_vs_f64m1_f64m1(
              vacc, __riscv_vfmv_v_f_f64m1(0.0, 1), vl);
          sum += __riscv_vfmv_f_s_f64m1_f64(vred);
          k += (int)(vl << 1);
        }
      }
      for (; k < _PB_N; )
      {
        size_t vl = __riscv_vsetvl_e64m1(_PB_N - k);
        vfloat64m1_t vi = __riscv_vlse64_v_f64m1(&data[k][i], (ptrdiff_t)(m * sizeof(DATA_TYPE)), vl);
        vfloat64m1_t vj = __riscv_vlse64_v_f64m1(&data[k][j], (ptrdiff_t)(m * sizeof(DATA_TYPE)), vl);
        vfloat64m1_t vm = __riscv_vfmul_vv_f64m1(vi, vj, vl);
        vfloat64m1_t vred = __riscv_vfredusum_vs_f64m1_f64m1(
            vm, __riscv_vfmv_v_f_f64m1(0.0, 1), vl);
        sum += __riscv_vfmv_f_s_f64m1_f64(vred);
        k += (int)vl;
      }
#else
      for (k = 0; k < _PB_N; k++)
        sum += data[k][i] * data[k][j];
#endif
      corr[i][j] = sum;
      corr[j][i] = sum;
    }
  }
  corr[_PB_M - 1][_PB_M - 1] = SCALAR_VAL(1.0);
#pragma endscop
}

