static
void kernel_covariance(int m, int n,
		       DATA_TYPE float_n,
		       DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
		       DATA_TYPE POLYBENCH_2D(cov,M,M,m,m),
		       DATA_TYPE POLYBENCH_1D(mean,M,m))
{
  int i, j, k;

#pragma scop
#if defined(__riscv_vector) && defined(DATA_TYPE_IS_FLOAT)
  for (j = 0; j < _PB_M; ) {
    size_t vl = __riscv_vsetvl_e32m1(_PB_M - j);
    __riscv_vse32_v_f32m1(&mean[j], __riscv_vfmv_v_f_f32m1(0.0f, vl), vl);
    j += vl;
  }

  for (i = 0; i < _PB_N; i++) {
    for (j = 0; j < _PB_M; ) {
      size_t vl = __riscv_vsetvl_e32m1(_PB_M - j);
      vfloat32m1_t vmean = __riscv_vle32_v_f32m1(&mean[j], vl);
      vfloat32m1_t vdata = __riscv_vle32_v_f32m1(&data[i][j], vl);
      vmean = __riscv_vfadd_vv_f32m1(vmean, vdata, vl);
      __riscv_vse32_v_f32m1(&mean[j], vmean, vl);
      j += vl;
    }
  }

  {
    DATA_TYPE inv_float_n = SCALAR_VAL(1.0) / float_n;
    for (j = 0; j < _PB_M; ) {
      size_t vl = __riscv_vsetvl_e32m1(_PB_M - j);
      vfloat32m1_t vmean = __riscv_vle32_v_f32m1(&mean[j], vl);
      vmean = __riscv_vfmul_vf_f32m1(vmean, inv_float_n, vl);
      __riscv_vse32_v_f32m1(&mean[j], vmean, vl);
      j += vl;
    }
  }

  for (i = 0; i < _PB_N; i++) {
    for (j = 0; j < _PB_M; ) {
      size_t vl = __riscv_vsetvl_e32m1(_PB_M - j);
      vfloat32m1_t vdata = __riscv_vle32_v_f32m1(&data[i][j], vl);
      vfloat32m1_t vmean = __riscv_vle32_v_f32m1(&mean[j], vl);
      vdata = __riscv_vfsub_vv_f32m1(vdata, vmean, vl);
      __riscv_vse32_v_f32m1(&data[i][j], vdata, vl);
      j += vl;
    }
  }

  {
    DATA_TYPE denom = float_n - SCALAR_VAL(1.0);
    DATA_TYPE inv_denom = SCALAR_VAL(1.0) / denom;

    for (i = 0; i < _PB_M; i++) {
      for (j = i; j < _PB_M; j++) {
        vfloat32m1_t vacc = __riscv_vfmv_v_f_f32m1(0.0f, __riscv_vsetvl_e32m1(_PB_N));
        int kk = 0;

        for (; kk < _PB_N; ) {
          size_t vl = __riscv_vsetvl_e32m1(_PB_N - kk);
          vfloat32m1_t vxi = __riscv_vlse32_v_f32m1(&data[kk][i], (ptrdiff_t)(_PB_M * sizeof(DATA_TYPE)), vl);
          vfloat32m1_t vxj = __riscv_vlse32_v_f32m1(&data[kk][j], (ptrdiff_t)(_PB_M * sizeof(DATA_TYPE)), vl);
          vacc = __riscv_vfmacc_vv_f32m1(vacc, vxi, vxj, vl);
          kk += vl;
        }

        DATA_TYPE sum = __riscv_vfmv_f_s_f32m1_f32(vacc);
        size_t vlr = __riscv_vsetvl_e32m1(__riscv_vsetvlmax_e32m1());
        for (size_t offset = 1; offset < vlr; offset <<= 1) {
          vfloat32m1_t vtmp = __riscv_vslidedown_vx_f32m1(vacc, offset, vlr);
          vacc = __riscv_vfadd_vv_f32m1(vacc, vtmp, vlr);
        }
        sum = __riscv_vfmv_f_s_f32m1_f32(vacc);

        sum *= inv_denom;
        cov[i][j] = sum;
        cov[j][i] = sum;
      }
    }
  }
#else
  for (j = 0; j < _PB_M; j++)
    {
      mean[j] = SCALAR_VAL(0.0);
      for (i = 0; i < _PB_N; i++)
        mean[j] += data[i][j];
      mean[j] /= float_n;
    }

  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_M; j++)
      data[i][j] -= mean[j];

  for (i = 0; i < _PB_M; i++)
    for (j = i; j < _PB_M; j++)
      {
        cov[i][j] = SCALAR_VAL(0.0);
        for (k = 0; k < _PB_N; k++)
	  cov[i][j] += data[k][i] * data[k][j];
        cov[i][j] /= (float_n - SCALAR_VAL(1.0));
        cov[j][i] = cov[i][j];
      }
#endif
#pragma endscop

}

