static
void kernel_deriche(int w, int h, DATA_TYPE alpha,
       DATA_TYPE POLYBENCH_2D(imgIn, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(imgOut, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(y1, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(y2, W, H, w, h)) {
    int i, j;
    DATA_TYPE xm1, tm1, ym1, ym2;
    DATA_TYPE xp1, xp2;
    DATA_TYPE tp1, tp2;
    DATA_TYPE yp1, yp2;

    DATA_TYPE k;
    DATA_TYPE a1, a2, a3, a4, a5, a6, a7, a8;
    DATA_TYPE b1, b2, c1, c2;

#pragma scop
    k = (SCALAR_VAL(1.0)-EXP_FUN(-alpha))*(SCALAR_VAL(1.0)-EXP_FUN(-alpha))/
        (SCALAR_VAL(1.0)+SCALAR_VAL(2.0)*alpha*EXP_FUN(-alpha)-EXP_FUN(SCALAR_VAL(2.0)*alpha));
    a1 = a5 = k;
    a2 = a6 = k*EXP_FUN(-alpha)*(alpha-SCALAR_VAL(1.0));
    a3 = a7 = k*EXP_FUN(-alpha)*(alpha+SCALAR_VAL(1.0));
    a4 = a8 = -k*EXP_FUN(SCALAR_VAL(-2.0)*alpha);
    b1 = POW_FUN(SCALAR_VAL(2.0),-alpha);
    b2 = -EXP_FUN(SCALAR_VAL(-2.0)*alpha);
    c1 = c2 = 1;

    for (i = 0; i < _PB_W; i++) {
        DATA_TYPE *imgIn_i = &imgIn[i][0];
        DATA_TYPE *y1_i = &y1[i][0];
        ym1 = SCALAR_VAL(0.0);
        ym2 = SCALAR_VAL(0.0);
        xm1 = SCALAR_VAL(0.0);
        for (j = 0; j < _PB_H; j++) {
            DATA_TYPE x = imgIn_i[j];
            DATA_TYPE y = a1 * x + a2 * xm1 + b1 * ym1 + b2 * ym2;
            y1_i[j] = y;
            xm1 = x;
            ym2 = ym1;
            ym1 = y;
        }
    }

    for (i = 0; i < _PB_W; i++) {
        DATA_TYPE *imgIn_i = &imgIn[i][0];
        DATA_TYPE *y2_i = &y2[i][0];
        yp1 = SCALAR_VAL(0.0);
        yp2 = SCALAR_VAL(0.0);
        xp1 = SCALAR_VAL(0.0);
        xp2 = SCALAR_VAL(0.0);
        for (j = _PB_H - 1; j >= 0; j--) {
            DATA_TYPE y = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
            y2_i[j] = y;
            xp2 = xp1;
            xp1 = imgIn_i[j];
            yp2 = yp1;
            yp1 = y;
        }
    }

    for (i = 0; i < _PB_W; i++) {
        DATA_TYPE *imgOut_i = &imgOut[i][0];
        DATA_TYPE *y1_i = &y1[i][0];
        DATA_TYPE *y2_i = &y2[i][0];
        j = 0;
#if defined(__riscv_vector)
#if defined(DATA_TYPE_IS_DOUBLE)
        for (; j < _PB_H; ) {
            size_t vl = __riscv_vsetvl_e64m4((size_t)(_PB_H - j));
            vfloat64m4_t vy1 = __riscv_vle64_v_f64m4(&y1_i[j], vl);
            vfloat64m4_t vy2 = __riscv_vle64_v_f64m4(&y2_i[j], vl);
            vfloat64m4_t vs = __riscv_vfadd_vv_f64m4(vy1, vy2, vl);
            __riscv_vse64_v_f64m4(&imgOut_i[j], vs, vl);
            j += (int)vl;
        }
#elif defined(DATA_TYPE_IS_FLOAT)
        for (; j < _PB_H; ) {
            size_t vl = __riscv_vsetvl_e32m8((size_t)(_PB_H - j));
            vfloat32m8_t vy1 = __riscv_vle32_v_f32m8(&y1_i[j], vl);
            vfloat32m8_t vy2 = __riscv_vle32_v_f32m8(&y2_i[j], vl);
            vfloat32m8_t vs = __riscv_vfadd_vv_f32m8(vy1, vy2, vl);
            __riscv_vse32_v_f32m8(&imgOut_i[j], vs, vl);
            j += (int)vl;
        }
#endif
#endif
        for (; j < _PB_H; j++) {
            imgOut_i[j] = c1 * (y1_i[j] + y2_i[j]);
        }
    }

    for (j = 0; j < _PB_H; j++) {
        tm1 = SCALAR_VAL(0.0);
        ym1 = SCALAR_VAL(0.0);
        ym2 = SCALAR_VAL(0.0);
        for (i = 0; i < _PB_W; i++) {
            DATA_TYPE x = imgOut[i][j];
            DATA_TYPE y = a5 * x + a6 * tm1 + b1 * ym1 + b2 * ym2;
            y1[i][j] = y;
            tm1 = x;
            ym2 = ym1;
            ym1 = y;
        }
    }

    for (j = 0; j < _PB_H; j++) {
        tp1 = SCALAR_VAL(0.0);
        tp2 = SCALAR_VAL(0.0);
        yp1 = SCALAR_VAL(0.0);
        yp2 = SCALAR_VAL(0.0);
        for (i = _PB_W - 1; i >= 0; i--) {
            DATA_TYPE y = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;
            y2[i][j] = y;
            tp2 = tp1;
            tp1 = imgOut[i][j];
            yp2 = yp1;
            yp1 = y;
        }
    }

    for (i = 0; i < _PB_W; i++) {
        DATA_TYPE *imgOut_i = &imgOut[i][0];
        DATA_TYPE *y1_i = &y1[i][0];
        DATA_TYPE *y2_i = &y2[i][0];
        j = 0;
#if defined(__riscv_vector)
#if defined(DATA_TYPE_IS_DOUBLE)
        for (; j < _PB_H; ) {
            size_t vl = __riscv_vsetvl_e64m4((size_t)(_PB_H - j));
            vfloat64m4_t vy1 = __riscv_vle64_v_f64m4(&y1_i[j], vl);
            vfloat64m4_t vy2 = __riscv_vle64_v_f64m4(&y2_i[j], vl);
            vfloat64m4_t vs = __riscv_vfadd_vv_f64m4(vy1, vy2, vl);
            __riscv_vse64_v_f64m4(&imgOut_i[j], vs, vl);
            j += (int)vl;
        }
#elif defined(DATA_TYPE_IS_FLOAT)
        for (; j < _PB_H; ) {
            size_t vl = __riscv_vsetvl_e32m8((size_t)(_PB_H - j));
            vfloat32m8_t vy1 = __riscv_vle32_v_f32m8(&y1_i[j], vl);
            vfloat32m8_t vy2 = __riscv_vle32_v_f32m8(&y2_i[j], vl);
            vfloat32m8_t vs = __riscv_vfadd_vv_f32m8(vy1, vy2, vl);
            __riscv_vse32_v_f32m8(&imgOut_i[j], vs, vl);
            j += (int)vl;
        }
#endif
#endif
        for (; j < _PB_H; j++) {
            imgOut_i[j] = c2 * (y1_i[j] + y2_i[j]);
        }
    }

#pragma endscop
}

