void kernel_doitgen(int nr, int nq, int np,
		    DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np),
		    DATA_TYPE POLYBENCH_2D(C4,NP,NP,np,np),
		    DATA_TYPE POLYBENCH_1D(sum,NP,np))
{
  int r, q, p, s;

#pragma scop
  for (r = 0; r < _PB_NR; r++) {
    for (q = 0; q < _PB_NQ; q++) {
      DATA_TYPE *Arq = &A[r][q][0];

#if defined(__riscv_vector) && defined(DATA_TYPE_IS_FLOAT)
      {
        int rem_init = _PB_NP;
        int idx_init = 0;
        while (rem_init > 0) {
          size_t vl = __riscv_vsetvl_e32m1(rem_init);
          __riscv_vse32_v_f32m1((float *)&sum[idx_init], __riscv_vfmv_v_f_f32m1(0.0f, vl), vl);
          idx_init += (int)vl;
          rem_init -= (int)vl;
        }
      }

      for (s = 0; s < _PB_NP; s++) {
        const float a_scalar = (float)Arq[s];
        const float *c4_row = (const float *)&C4[s][0];
        int rem = _PB_NP;
        int idx = 0;

        while (rem > 0) {
          size_t vl = __riscv_vsetvl_e32m1(rem);
          vfloat32m1_t v_sum = __riscv_vle32_v_f32m1((const float *)&sum[idx], vl);
          vfloat32m1_t v_c4  = __riscv_vle32_v_f32m1(&c4_row[idx], vl);
          v_sum = __riscv_vfmacc_vf_f32m1(v_sum, a_scalar, v_c4, vl);
          __riscv_vse32_v_f32m1((float *)&sum[idx], v_sum, vl);
          idx += (int)vl;
          rem -= (int)vl;
        }
      }

      {
        int rem_store = _PB_NP;
        int idx_store = 0;
        while (rem_store > 0) {
          size_t vl = __riscv_vsetvl_e32m1(rem_store);
          vfloat32m1_t v_sum = __riscv_vle32_v_f32m1((const float *)&sum[idx_store], vl);
          __riscv_vse32_v_f32m1((float *)&Arq[idx_store], v_sum, vl);
          idx_store += (int)vl;
          rem_store -= (int)vl;
        }
      }

#elif defined(__riscv_vector) && defined(DATA_TYPE_IS_DOUBLE)
      {
        int rem_init = _PB_NP;
        int idx_init = 0;
        while (rem_init > 0) {
          size_t vl = __riscv_vsetvl_e64m1(rem_init);
          __riscv_vse64_v_f64m1((double *)&sum[idx_init], __riscv_vfmv_v_f_f64m1(0.0, vl), vl);
          idx_init += (int)vl;
          rem_init -= (int)vl;
        }
      }

      for (s = 0; s < _PB_NP; s++) {
        const double a_scalar = (double)Arq[s];
        const double *c4_row = (const double *)&C4[s][0];
        int rem = _PB_NP;
        int idx = 0;

        while (rem > 0) {
          size_t vl = __riscv_vsetvl_e64m1(rem);
          vfloat64m1_t v_sum = __riscv_vle64_v_f64m1((const double *)&sum[idx], vl);
          vfloat64m1_t v_c4  = __riscv_vle64_v_f64m1(&c4_row[idx], vl);
          v_sum = __riscv_vfmacc_vf_f64m1(v_sum, a_scalar, v_c4, vl);
          __riscv_vse64_v_f64m1((double *)&sum[idx], v_sum, vl);
          idx += (int)vl;
          rem -= (int)vl;
        }
      }

      {
        int rem_store = _PB_NP;
        int idx_store = 0;
        while (rem_store > 0) {
          size_t vl = __riscv_vsetvl_e64m1(rem_store);
          vfloat64m1_t v_sum = __riscv_vle64_v_f64m1((const double *)&sum[idx_store], vl);
          __riscv_vse64_v_f64m1((double *)&Arq[idx_store], v_sum, vl);
          idx_store += (int)vl;
          rem_store -= (int)vl;
        }
      }
#else
      for (p = 0; p < _PB_NP; p++) {
	sum[p] = SCALAR_VAL(0.0);
	for (s = 0; s < _PB_NP; s++)
	  sum[p] += Arq[s] * C4[s][p];
      }
      for (p = 0; p < _PB_NP; p++)
	Arq[p] = sum[p];
#endif
    }
  }
#pragma endscop
}

