static
void kernel_durbin(int n,
		   DATA_TYPE POLYBENCH_1D(r,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  DATA_TYPE z[N];
  DATA_TYPE alpha;
  DATA_TYPE beta;
  DATA_TYPE sum;

  int i, k;

#pragma scop
  y[0] = -r[0];
  beta = SCALAR_VAL(1.0);
  alpha = -r[0];

  for (k = 1; k < _PB_N; k++) {
    beta = (SCALAR_VAL(1.0) - alpha * alpha) * beta;
    sum = SCALAR_VAL(0.0);

#if defined(__riscv_vector) && defined(DATA_TYPE_IS_FLOAT)
    {
      int rem = k;
      int base = 0;
      DATA_TYPE accum = SCALAR_VAL(0.0);

      while (rem > 0) {
        size_t vl = __riscv_vsetvl_e32m1((size_t)rem);
        vfloat32m1_t vy = __riscv_vle32_v_f32m1(&y[base], vl);
        vfloat32m1_t vrseg = __riscv_vle32_v_f32m1(&r[k - base - (int)vl], vl);
        vuint32m1_t vidx = __riscv_vid_v_u32m1(vl);
        vuint32m1_t ridx = __riscv_vrsub_vx_u32m1(vidx, (uint32_t)(vl - 1), vl);
        vfloat32m1_t vr = __riscv_vrgather_vv_f32m1(vrseg, ridx, vl);
        vfloat32m1_t vm = __riscv_vfmul_vv_f32m1(vr, vy, vl);
        vfloat32m1_t vzero = __riscv_vfmv_v_f_f32m1(SCALAR_VAL(0.0), vl);
        vfloat32m1_t vred = __riscv_vfredusum_vs_f32m1_f32m1(vm, vzero, vzero, vl);
        accum += __riscv_vfmv_f_s_f32m1_f32(vred);

        base += (int)vl;
        rem -= (int)vl;
      }
      sum = accum;
    }
#elif defined(__riscv_vector) && defined(DATA_TYPE_IS_DOUBLE)
    {
      int rem = k;
      int base = 0;
      DATA_TYPE accum = SCALAR_VAL(0.0);

      while (rem > 0) {
        size_t vl = __riscv_vsetvl_e64m1((size_t)rem);
        vfloat64m1_t vy = __riscv_vle64_v_f64m1(&y[base], vl);
        vfloat64m1_t vrseg = __riscv_vle64_v_f64m1(&r[k - base - (int)vl], vl);
        vuint64m1_t vidx = __riscv_vid_v_u64m1(vl);
        vuint64m1_t ridx = __riscv_vrsub_vx_u64m1(vidx, (uint64_t)(vl - 1), vl);
        vfloat64m1_t vr = __riscv_vrgather_vv_f64m1(vrseg, ridx, vl);
        vfloat64m1_t vm = __riscv_vfmul_vv_f64m1(vr, vy, vl);
        vfloat64m1_t vzero = __riscv_vfmv_v_f_f64m1(SCALAR_VAL(0.0), vl);
        vfloat64m1_t vred = __riscv_vfredusum_vs_f64m1_f64m1(vm, vzero, vzero, vl);
        accum += __riscv_vfmv_f_s_f64m1_f64(vred);

        base += (int)vl;
        rem -= (int)vl;
      }
      sum = accum;
    }
#else
    for (i = 0; i < k; i++) {
      sum += r[k - i - 1] * y[i];
    }
#endif

    alpha = -(r[k] + sum) / beta;

#if defined(__riscv_vector) && defined(DATA_TYPE_IS_FLOAT)
    {
      int rem = k;
      int base = 0;

      while (rem > 0) {
        size_t vl = __riscv_vsetvl_e32m1((size_t)rem);
        vfloat32m1_t vy_l = __riscv_vle32_v_f32m1(&y[base], vl);
        vfloat32m1_t vy_r_seg = __riscv_vle32_v_f32m1(&y[k - base - (int)vl], vl);
        vuint32m1_t vidx = __riscv_vid_v_u32m1(vl);
        vuint32m1_t ridx = __riscv_vrsub_vx_u32m1(vidx, (uint32_t)(vl - 1), vl);
        vfloat32m1_t vy_r = __riscv_vrgather_vv_f32m1(vy_r_seg, ridx, vl);
        vfloat32m1_t vz = __riscv_vfmacc_vf_f32m1(vy_l, alpha, vy_r, vl);
        __riscv_vse32_v_f32m1(&z[base], vz, vl);

        base += (int)vl;
        rem -= (int)vl;
      }

      rem = k;
      base = 0;
      while (rem > 0) {
        size_t vl = __riscv_vsetvl_e32m1((size_t)rem);
        vfloat32m1_t vz = __riscv_vle32_v_f32m1(&z[base], vl);
        __riscv_vse32_v_f32m1(&y[base], vz, vl);
        base += (int)vl;
        rem -= (int)vl;
      }
    }
#elif defined(__riscv_vector) && defined(DATA_TYPE_IS_DOUBLE)
    {
      int rem = k;
      int base = 0;

      while (rem > 0) {
        size_t vl = __riscv_vsetvl_e64m1((size_t)rem);
        vfloat64m1_t vy_l = __riscv_vle64_v_f64m1(&y[base], vl);
        vfloat64m1_t vy_r_seg = __riscv_vle64_v_f64m1(&y[k - base - (int)vl], vl);
        vuint64m1_t vidx = __riscv_vid_v_u64m1(vl);
        vuint64m1_t ridx = __riscv_vrsub_vx_u64m1(vidx, (uint64_t)(vl - 1), vl);
        vfloat64m1_t vy_r = __riscv_vrgather_vv_f64m1(vy_r_seg, ridx, vl);
        vfloat64m1_t vz = __riscv_vfmacc_vf_f64m1(vy_l, alpha, vy_r, vl);
        __riscv_vse64_v_f64m1(&z[base], vz, vl);

        base += (int)vl;
        rem -= (int)vl;
      }

      rem = k;
      base = 0;
      while (rem > 0) {
        size_t vl = __riscv_vsetvl_e64m1((size_t)rem);
        vfloat64m1_t vz = __riscv_vle64_v_f64m1(&z[base], vl);
        __riscv_vse64_v_f64m1(&y[base], vz, vl);
        base += (int)vl;
        rem -= (int)vl;
      }
    }
#else
    for (i = 0; i < k; i++) {
      z[i] = y[i] + alpha * y[k - i - 1];
    }
    for (i = 0; i < k; i++) {
      y[i] = z[i];
    }
#endif

    y[k] = alpha;
  }
#pragma endscop
}

