static
void kernel_fdtd_2d(int tmax,
		    int nx,
		    int ny,
		    DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_1D(_fict_,TMAX,tmax))
{
  int t, i, j;

#pragma scop

#if defined(__riscv_vector)
#if defined(DATA_TYPE_IS_FLOAT)
  const float c05 = 0.5f;
  const float c07 = 0.7f;
  for (t = 0; t < _PB_TMAX; t++)
    {
      {
        DATA_TYPE *ey0 = &ey[0][0];
        DATA_TYPE ft = _fict_[t];
        int rem = _PB_NY, off = 0;
        while (rem > 0) {
          size_t vl = __riscv_vsetvl_e32m8((size_t)rem);
          vfloat32m8_t vft = __riscv_vfmv_v_f_f32m8((float)ft, vl);
          __riscv_vse32_v_f32m8((float *)(ey0 + off), vft, vl);
          off += (int)vl;
          rem -= (int)vl;
        }
      }

      for (i = 1; i < _PB_NX; i++) {
        DATA_TYPE *ey_row = &ey[i][0];
        DATA_TYPE *hz_row = &hz[i][0];
        DATA_TYPE *hz_prev = &hz[i - 1][0];
        int rem = _PB_NY, off = 0;
        while (rem > 0) {
          size_t vl = __riscv_vsetvl_e32m8((size_t)rem);
          vfloat32m8_t vey = __riscv_vle32_v_f32m8((const float *)(ey_row + off), vl);
          vfloat32m8_t vhz = __riscv_vle32_v_f32m8((const float *)(hz_row + off), vl);
          vfloat32m8_t vhzp = __riscv_vle32_v_f32m8((const float *)(hz_prev + off), vl);
          vfloat32m8_t vdiff = __riscv_vfsub_vv_f32m8(vhz, vhzp, vl);
          vey = __riscv_vfnmsac_vf_f32m8(vey, c05, vdiff, vl);
          __riscv_vse32_v_f32m8((float *)(ey_row + off), vey, vl);
          off += (int)vl;
          rem -= (int)vl;
        }
      }

      for (i = 0; i < _PB_NX; i++) {
        DATA_TYPE *ex_row = &ex[i][0];
        DATA_TYPE *hz_row = &hz[i][0];
        for (j = 1; j < _PB_NY; j++)
          ex_row[j] = ex_row[j] - c05 * (hz_row[j] - hz_row[j - 1]);
      }

      for (i = 0; i < _PB_NX - 1; i++) {
        DATA_TYPE *hz_row = &hz[i][0];
        DATA_TYPE *ex_row = &ex[i][0];
        DATA_TYPE *ey_row = &ey[i][0];
        DATA_TYPE *ey_next = &ey[i + 1][0];
        for (j = 0; j < _PB_NY - 1; j++)
          hz_row[j] = hz_row[j] - c07 * (ex_row[j + 1] - ex_row[j] +
                                         ey_next[j] - ey_row[j]);
      }
    }
#else
  for (t = 0; t < _PB_TMAX; t++)
    {
      for (j = 0; j < _PB_NY; j++)
        ey[0][j] = _fict_[t];
      for (i = 1; i < _PB_NX; i++)
        for (j = 0; j < _PB_NY; j++)
          ey[i][j] = ey[i][j] - SCALAR_VAL(0.5) * (hz[i][j] - hz[i-1][j]);
      for (i = 0; i < _PB_NX; i++)
        for (j = 1; j < _PB_NY; j++)
          ex[i][j] = ex[i][j] - SCALAR_VAL(0.5) * (hz[i][j] - hz[i][j-1]);
      for (i = 0; i < _PB_NX - 1; i++)
        for (j = 0; j < _PB_NY - 1; j++)
          hz[i][j] = hz[i][j] - SCALAR_VAL(0.7) * (ex[i][j+1] - ex[i][j] +
                                                    ey[i+1][j] - ey[i][j]);
    }
#endif
#else
  for(t = 0; t < _PB_TMAX; t++)
    {
      for (j = 0; j < _PB_NY; j++)
	ey[0][j] = _fict_[t];
      for (i = 1; i < _PB_NX; i++)
	for (j = 0; j < _PB_NY; j++)
	  ey[i][j] = ey[i][j] - SCALAR_VAL(0.5)*(hz[i][j]-hz[i-1][j]);
      for (i = 0; i < _PB_NX; i++)
	for (j = 1; j < _PB_NY; j++)
	  ex[i][j] = ex[i][j] - SCALAR_VAL(0.5)*(hz[i][j]-hz[i][j-1]);
      for (i = 0; i < _PB_NX - 1; i++)
	for (j = 0; j < _PB_NY - 1; j++)
	  hz[i][j] = hz[i][j] - SCALAR_VAL(0.7)*  (ex[i][j+1] - ex[i][j] +
				       ey[i+1][j] - ey[i][j]);
    }
#endif

#pragma endscop
}

