static
void kernel_floyd_warshall(int n,
			   DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
      DATA_TYPE * __restrict pk = path[k];

      for (i = 0; i < _PB_N; i++)
	{
	  DATA_TYPE * __restrict pi = path[i];
	  DATA_TYPE pik = pi[k];

#if defined(__riscv_vector)
	  int jj = 0;

#if defined(DATA_TYPE_IS_INT)
	  for (; jj < _PB_N; )
	    {
	      size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_N - jj));
	      vint32m1_t v_ij = __riscv_vle32_v_i32m1(&pi[jj], vl);
	      vint32m1_t v_kj = __riscv_vle32_v_i32m1(&pk[jj], vl);
	      vint32m1_t v_pik = __riscv_vmv_v_x_i32m1((int32_t)pik, vl);
	      vint32m1_t v_sum = __riscv_vadd_vv_i32m1(v_pik, v_kj, vl);
	      vbool32_t mask = __riscv_vmslt_vv_i32m1_b32(v_sum, v_ij, vl);
	      vint32m1_t v_res = __riscv_vmerge_vvm_i32m1(v_ij, v_sum, mask, vl);
	      __riscv_vse32_v_i32m1(&pi[jj], v_res, vl);
	      jj += (int)vl;
	    }
#elif defined(DATA_TYPE_IS_FLOAT)
	  for (; jj < _PB_N; )
	    {
	      size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_N - jj));
	      vfloat32m1_t v_ij = __riscv_vle32_v_f32m1(&pi[jj], vl);
	      vfloat32m1_t v_kj = __riscv_vle32_v_f32m1(&pk[jj], vl);
	      vfloat32m1_t v_pik = __riscv_vfmv_v_f_f32m1((float)pik, vl);
	      vfloat32m1_t v_sum = __riscv_vfadd_vv_f32m1(v_pik, v_kj, vl);
	      vbool32_t mask = __riscv_vmflt_vv_f32m1_b32(v_sum, v_ij, vl);
	      vfloat32m1_t v_res = __riscv_vmerge_vvm_f32m1(v_ij, v_sum, mask, vl);
	      __riscv_vse32_v_f32m1(&pi[jj], v_res, vl);
	      jj += (int)vl;
	    }
#elif defined(DATA_TYPE_IS_DOUBLE)
	  for (; jj < _PB_N; )
	    {
	      size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - jj));
	      vfloat64m1_t v_ij = __riscv_vle64_v_f64m1(&pi[jj], vl);
	      vfloat64m1_t v_kj = __riscv_vle64_v_f64m1(&pk[jj], vl);
	      vfloat64m1_t v_pik = __riscv_vfmv_v_f_f64m1((double)pik, vl);
	      vfloat64m1_t v_sum = __riscv_vfadd_vv_f64m1(v_pik, v_kj, vl);
	      vbool64_t mask = __riscv_vmflt_vv_f64m1_b64(v_sum, v_ij, vl);
	      vfloat64m1_t v_res = __riscv_vmerge_vvm_f64m1(v_ij, v_sum, mask, vl);
	      __riscv_vse64_v_f64m1(&pi[jj], v_res, vl);
	      jj += (int)vl;
	    }
#else
	  for (j = 0; j < _PB_N; j++)
	    {
	      DATA_TYPE alt = pik + pk[j];
	      pi[j] = pi[j] < alt ? pi[j] : alt;
	    }
#endif

#else
	  for (j = 0; j < _PB_N; j++)
	    {
	      DATA_TYPE alt = pik + pk[j];
	      pi[j] = pi[j] < alt ? pi[j] : alt;
	    }
#endif
	}
    }
#pragma endscop

}

