static
void kernel_gemm(int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_NI; i++) {
#if defined(__riscv_vector) && defined(DATA_TYPE_IS_DOUBLE)
    {
      int jv = 0;
      for (; jv < _PB_NJ; ) {
        size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_NJ - jv));
        vfloat64m1_t vc = __riscv_vle64_v_f64m1(&C[i][jv], vl);
        vc = __riscv_vfmul_vf_f64m1(vc, (double)beta, vl);
        __riscv_vse64_v_f64m1(&C[i][jv], vc, vl);
        jv += (int)vl;
      }
    }

    for (k = 0; k < _PB_NK; k++) {
      double aik_alpha = (double)alpha * (double)A[i][k];
      int jv = 0;
      for (; jv < _PB_NJ; ) {
        size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_NJ - jv));
        vfloat64m1_t vc = __riscv_vle64_v_f64m1(&C[i][jv], vl);
        vfloat64m1_t vb = __riscv_vle64_v_f64m1(&B[k][jv], vl);
        vc = __riscv_vfmacc_vf_f64m1(vc, aik_alpha, vb, vl);
        __riscv_vse64_v_f64m1(&C[i][jv], vc, vl);
        jv += (int)vl;
      }
    }
#elif defined(__riscv_vector)
    {
      int jv = 0;
      for (; jv < _PB_NJ; ) {
        size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_NJ - jv));
        vfloat32m1_t vc = __riscv_vle32_v_f32m1(&C[i][jv], vl);
        vc = __riscv_vfmul_vf_f32m1(vc, (float)beta, vl);
        __riscv_vse32_v_f32m1(&C[i][jv], vc, vl);
        jv += (int)vl;
      }
    }

    for (k = 0; k < _PB_NK; k++) {
      float aik_alpha = (float)alpha * (float)A[i][k];
      int jv = 0;
      for (; jv < _PB_NJ; ) {
        size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_NJ - jv));
        vfloat32m1_t vc = __riscv_vle32_v_f32m1(&C[i][jv], vl);
        vfloat32m1_t vb = __riscv_vle32_v_f32m1(&B[k][jv], vl);
        vc = __riscv_vfmacc_vf_f32m1(vc, aik_alpha, vb, vl);
        __riscv_vse32_v_f32m1(&C[i][jv], vc, vl);
        jv += (int)vl;
      }
    }
#else
    for (j = 0; j < _PB_NJ; j++)
      C[i][j] *= beta;
    for (k = 0; k < _PB_NK; k++) {
      DATA_TYPE a = alpha * A[i][k];
      for (j = 0; j < _PB_NJ; j++)
        C[i][j] += a * B[k][j];
    }
#endif
  }
#pragma endscop

}

