  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE sum = x[i];
#if defined(__riscv_vector)
    j = 0;
#if defined(DATA_TYPE_IS_DOUBLE)
    vfloat64m1_t vacc = __riscv_vfmv_v_f_f64m1(0.0, __riscv_vsetvl_e64m1(1));
    while (j < _PB_N) {
