      vfloat64m1_t vAcol = __riscv_vlse64_v_f64m1(&A[j][i], n * sizeof(DATA_TYPE), vl);
      vfloat64m1_t vy    = __riscv_vle64_v_f64m1(&y[j], vl);
      vacc = __riscv_vfmacc_vv_f64m1(vacc, vAcol, vy, vl);
      j += vl;
    }
    sum += beta * __riscv_vfmv_f_s_f64m1_f64(__riscv_vfredusum_vs_f64m1_f64m1(vacc, __riscv_vfmv_v_f_f64m1(0.0, __riscv_vsetvl_e64m1(1)), __riscv_vsetvl_e64m1(1)));
#elif defined(DATA_TYPE_IS_FLOAT)
    vfloat32m1_t vacc = __riscv_vfmv_v_f_f32m1(0.0f, __riscv_vsetvl_e32m1(1));
    while (j < _PB_N) {
      size_t vl = __riscv_vsetvl_e32m1(_PB_N - j);
      vfloat32m1_t vAcol = __riscv_vlse32_v_f32m1(&A[j][i], n * sizeof(DATA_TYPE), vl);
      vfloat32m1_t vy    = __riscv_vle32_v_f32m1(&y[j], vl);
      vacc = __riscv_vfmacc_vv_f32m1(vacc, vAcol, vy, vl);
      j += vl;
    }
    sum += beta * __riscv_vfmv_f_s_f32m1_f32(__riscv_vfredusum_vs_f32m1_f32m1(vacc, __riscv_vfmv_v_f_f32m1(0.0f, __riscv_vsetvl_e32m1(1)), __riscv_vsetvl_e32m1(1)));
#else
    for (j = 0; j < _PB_N; j++)
