static
void kernel_gesummv(int n,
		    DATA_TYPE alpha,
		    DATA_TYPE beta,
		    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		    DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(tmp,N,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j;

#pragma scop
#if defined(__riscv_vector) && defined(DATA_TYPE_IS_DOUBLE)
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE tmp_acc = SCALAR_VAL(0.0);
      DATA_TYPE y_acc = SCALAR_VAL(0.0);
      int rem = _PB_N;
      j = 0;
      vfloat64m1_t vtmp_sum = __riscv_vfmv_v_f_f64m1(SCALAR_VAL(0.0), __riscv_vsetvl_e64m1(_PB_N));
      vfloat64m1_t vy_sum = __riscv_vfmv_v_f_f64m1(SCALAR_VAL(0.0), __riscv_vsetvl_e64m1(_PB_N));

      while (rem > 0)
	{
	  size_t vl = __riscv_vsetvl_e64m1(rem);
	  vfloat64m1_t vx = __riscv_vle64_v_f64m1(&x[j], vl);
	  vfloat64m1_t va = __riscv_vle64_v_f64m1(&A[i][j], vl);
	  vfloat64m1_t vb = __riscv_vle64_v_f64m1(&B[i][j], vl);
	  vtmp_sum = __riscv_vfmacc_vv_f64m1(vtmp_sum, va, vx, vl);
	  vy_sum = __riscv_vfmacc_vv_f64m1(vy_sum, vb, vx, vl);
	  j += (int)vl;
	  rem -= (int)vl;
	}

      {
	size_t vlr = __riscv_vsetvl_e64m1(_PB_N);
	vfloat64m1_t vzero = __riscv_vfmv_v_f_f64m1(SCALAR_VAL(0.0), 1);
	vfloat64m1_t vtmp_red = __riscv_vfredusum_vs_f64m1_f64m1(vtmp_sum, vzero, vlr);
	vfloat64m1_t vy_red = __riscv_vfredusum_vs_f64m1_f64m1(vy_sum, vzero, vlr);
	tmp_acc = __riscv_vfmv_f_s_f64m1_f64(vtmp_red);
	y_acc = __riscv_vfmv_f_s_f64m1_f64(vy_red);
      }

      tmp[i] = tmp_acc;
      y[i] = alpha * tmp_acc + beta * y_acc;
    }
#elif defined(__riscv_vector) && defined(DATA_TYPE_IS_FLOAT)
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE tmp_acc = SCALAR_VAL(0.0);
      DATA_TYPE y_acc = SCALAR_VAL(0.0);
      int rem = _PB_N;
      j = 0;
      vfloat32m1_t vtmp_sum = __riscv_vfmv_v_f_f32m1(SCALAR_VAL(0.0), __riscv_vsetvl_e32m1(_PB_N));
      vfloat32m1_t vy_sum = __riscv_vfmv_v_f_f32m1(SCALAR_VAL(0.0), __riscv_vsetvl_e32m1(_PB_N));

      while (rem > 0)
	{
	  size_t vl = __riscv_vsetvl_e32m1(rem);
	  vfloat32m1_t vx = __riscv_vle32_v_f32m1(&x[j], vl);
	  vfloat32m1_t va = __riscv_vle32_v_f32m1(&A[i][j], vl);
	  vfloat32m1_t vb = __riscv_vle32_v_f32m1(&B[i][j], vl);
	  vtmp_sum = __riscv_vfmacc_vv_f32m1(vtmp_sum, va, vx, vl);
	  vy_sum = __riscv_vfmacc_vv_f32m1(vy_sum, vb, vx, vl);
	  j += (int)vl;
	  rem -= (int)vl;
	}

      {
	size_t vlr = __riscv_vsetvl_e32m1(_PB_N);
	vfloat32m1_t vzero = __riscv_vfmv_v_f_f32m1(SCALAR_VAL(0.0), 1);
	vfloat32m1_t vtmp_red = __riscv_vfredusum_vs_f32m1_f32m1(vtmp_sum, vzero, vlr);
	vfloat32m1_t vy_red = __riscv_vfredusum_vs_f32m1_f32m1(vy_sum, vzero, vlr);
	tmp_acc = __riscv_vfmv_f_s_f32m1_f32(vtmp_red);
	y_acc = __riscv_vfmv_f_s_f32m1_f32(vy_red);
      }

      tmp[i] = tmp_acc;
      y[i] = alpha * tmp_acc + beta * y_acc;
    }
#else
  for (i = 0; i < _PB_N; i++)
    {
      tmp[i] = SCALAR_VAL(0.0);
      y[i] = SCALAR_VAL(0.0);
      for (j = 0; j < _PB_N; j++)
	{
	  tmp[i] = A[i][j] * x[j] + tmp[i];
	  y[i] = B[i][j] * x[j] + y[i];
	}
      y[i] = alpha * tmp[i] + beta * y[i];
    }
#endif
#pragma endscop

}

