static
void kernel_gramschmidt(int m, int n,
			DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
			DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
			DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j, k;
  DATA_TYPE nrm;

#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
      nrm = SCALAR_VAL(0.0);

#if defined(__riscv_vector) && defined(DATA_TYPE_IS_DOUBLE)
      {
        int idx = 0;
        const DATA_TYPE *Ak = &A[0][k];
        vfloat64m1_t vsum = __riscv_vfmv_v_f_f64m1(0.0, 1);

        while (idx < _PB_M) {
          size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_M - idx));
          ptrdiff_t bstride = (ptrdiff_t)n * (ptrdiff_t)sizeof(DATA_TYPE);
          vfloat64m1_t va = __riscv_vlse64_v_f64m1(Ak + idx * n, bstride, vl);
          vsum = __riscv_vfredusum_vs_f64m1_f64m1(
              __riscv_vfmul_vv_f64m1(va, va, vl), vsum, vl);
          idx += (int)vl;
        }

        double redbuf[1];
        __riscv_vse64_v_f64m1(redbuf, vsum, 1);
        nrm = (DATA_TYPE)redbuf[0];
      }
#elif defined(__riscv_vector) && defined(DATA_TYPE_IS_FLOAT)
      {
        int idx = 0;
        const DATA_TYPE *Ak = &A[0][k];
        vfloat32m1_t vsum = __riscv_vfmv_v_f_f32m1(0.0f, 1);

        while (idx < _PB_M) {
          size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_M - idx));
          ptrdiff_t bstride = (ptrdiff_t)n * (ptrdiff_t)sizeof(DATA_TYPE);
          vfloat32m1_t va = __riscv_vlse32_v_f32m1(Ak + idx * n, bstride, vl);
          vsum = __riscv_vfredusum_vs_f32m1_f32m1(
              __riscv_vfmul_vv_f32m1(va, va, vl), vsum, vl);
          idx += (int)vl;
        }

        float redbuf[1];
        __riscv_vse32_v_f32m1(redbuf, vsum, 1);
        nrm = (DATA_TYPE)redbuf[0];
      }
#else
      for (i = 0; i < _PB_M; i++)
        nrm += A[i][k] * A[i][k];
#endif

      R[k][k] = SQRT_FUN(nrm);

      {
        DATA_TYPE rkk = R[k][k];

#if defined(__riscv_vector) && defined(DATA_TYPE_IS_DOUBLE)
        {
          int idx = 0;
          const DATA_TYPE *Ak = &A[0][k];
          DATA_TYPE *Qk = &Q[0][k];
          ptrdiff_t bstride = (ptrdiff_t)n * (ptrdiff_t)sizeof(DATA_TYPE);

          while (idx < _PB_M) {
            size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_M - idx));
            vfloat64m1_t va = __riscv_vlse64_v_f64m1(Ak + idx * n, bstride, vl);
            vfloat64m1_t vq = __riscv_vfdiv_vf_f64m1(va, rkk, vl);
            __riscv_vsse64_v_f64m1(Qk + idx * n, bstride, vq, vl);
            idx += (int)vl;
          }
        }
#elif defined(__riscv_vector) && defined(DATA_TYPE_IS_FLOAT)
        {
          int idx = 0;
          const DATA_TYPE *Ak = &A[0][k];
          DATA_TYPE *Qk = &Q[0][k];
          ptrdiff_t bstride = (ptrdiff_t)n * (ptrdiff_t)sizeof(DATA_TYPE);

          while (idx < _PB_M) {
            size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_M - idx));
            vfloat32m1_t va = __riscv_vlse32_v_f32m1(Ak + idx * n, bstride, vl);
            vfloat32m1_t vq = __riscv_vfdiv_vf_f32m1(va, rkk, vl);
            __riscv_vsse32_v_f32m1(Qk + idx * n, bstride, vq, vl);
            idx += (int)vl;
          }
        }
#else
        for (i = 0; i < _PB_M; i++)
          Q[i][k] = A[i][k] / rkk;
#endif
      }

      for (j = k + 1; j < _PB_N; j++)
	{
#if defined(__riscv_vector) && defined(DATA_TYPE_IS_DOUBLE)
          {
            int idx = 0;
            const DATA_TYPE *Qk = &Q[0][k];
            const DATA_TYPE *Aj = &A[0][j];
            ptrdiff_t bstride = (ptrdiff_t)n * (ptrdiff_t)sizeof(DATA_TYPE);
            vfloat64m1_t vsum = __riscv_vfmv_v_f_f64m1(0.0, 1);

            while (idx < _PB_M) {
              size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_M - idx));
              vfloat64m1_t vq = __riscv_vlse64_v_f64m1(Qk + idx * n, bstride, vl);
              vfloat64m1_t va = __riscv_vlse64_v_f64m1(Aj + idx * n, bstride, vl);
              vsum = __riscv_vfredusum_vs_f64m1_f64m1(
                  __riscv_vfmul_vv_f64m1(vq, va, vl), vsum, vl);
              idx += (int)vl;
            }

            {
              double redbuf[1];
              __riscv_vse64_v_f64m1(redbuf, vsum, 1);
              R[k][j] = (DATA_TYPE)redbuf[0];
            }
          }

          {
            int idx = 0;
            const DATA_TYPE *Qk = &Q[0][k];
            DATA_TYPE *Aj = &A[0][j];
            DATA_TYPE rkj = R[k][j];
            ptrdiff_t bstride = (ptrdiff_t)n * (ptrdiff_t)sizeof(DATA_TYPE);

            while (idx < _PB_M) {
              size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_M - idx));
              vfloat64m1_t vq = __riscv_vlse64_v_f64m1(Qk + idx * n, bstride, vl);
              vfloat64m1_t va = __riscv_vlse64_v_f64m1(Aj + idx * n, bstride, vl);
              va = __riscv_vfnmsac_vf_f64m1(va, rkj, vq, vl);
              __riscv_vsse64_v_f64m1(Aj + idx * n, bstride, va, vl);
              idx += (int)vl;
            }
          }
#elif defined(__riscv_vector) && defined(DATA_TYPE_IS_FLOAT)
          {
            int idx = 0;
            const DATA_TYPE *Qk = &Q[0][k];
            const DATA_TYPE *Aj = &A[0][j];
            ptrdiff_t bstride = (ptrdiff_t)n * (ptrdiff_t)sizeof(DATA_TYPE);
            vfloat32m1_t vsum = __riscv_vfmv_v_f_f32m1(0.0f, 1);

            while (idx < _PB_M) {
              size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_M - idx));
              vfloat32m1_t vq = __riscv_vlse32_v_f32m1(Qk + idx * n, bstride, vl);
              vfloat32m1_t va = __riscv_vlse32_v_f32m1(Aj + idx * n, bstride, vl);
              vsum = __riscv_vfredusum_vs_f32m1_f32m1(
                  __riscv_vfmul_vv_f32m1(vq, va, vl), vsum, vl);
              idx += (int)vl;
            }

            {
              float redbuf[1];
              __riscv_vse32_v_f32m1(redbuf, vsum, 1);
              R[k][j] = (DATA_TYPE)redbuf[0];
            }
          }

          {
            int idx = 0;
            const DATA_TYPE *Qk = &Q[0][k];
            DATA_TYPE *Aj = &A[0][j];
            DATA_TYPE rkj = R[k][j];
            ptrdiff_t bstride = (ptrdiff_t)n * (ptrdiff_t)sizeof(DATA_TYPE);

            while (idx < _PB_M) {
              size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_M - idx));
              vfloat32m1_t vq = __riscv_vlse32_v_f32m1(Qk + idx * n, bstride, vl);
              vfloat32m1_t va = __riscv_vlse32_v_f32m1(Aj + idx * n, bstride, vl);
              va = __riscv_vfnmsac_vf_f32m1(va, rkj, vq, vl);
              __riscv_vsse32_v_f32m1(Aj + idx * n, bstride, va, vl);
              idx += (int)vl;
            }
          }
#else
	  R[k][j] = SCALAR_VAL(0.0);
	  for (i = 0; i < _PB_M; i++)
	    R[k][j] += Q[i][k] * A[i][j];
	  for (i = 0; i < _PB_M; i++)
	    A[i][j] = A[i][j] - Q[i][k] * R[k][j];
#endif
	}
    }
#pragma endscop

}

