static
void kernel_heat_3d(int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
		      DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  int t, i, j, k;

#pragma scop
  for (t = 1; t <= TSTEPS; t++) {
    for (i = 1; i < _PB_N-1; i++) {
      for (j = 1; j < _PB_N-1; j++) {

#if defined(__riscv_vector) && defined(DATA_TYPE_IS_FLOAT)
        {
          const float c0 = 0.125f;
          const float c6 = 0.75f;
          DATA_TYPE *restrict b_row = &B[i][j][1];
          DATA_TYPE *restrict a_row = &A[i][j][1];
          DATA_TYPE *restrict axp   = &A[i+1][j][1];
          DATA_TYPE *restrict axm   = &A[i-1][j][1];
          DATA_TYPE *restrict ayp   = &A[i][j+1][1];
          DATA_TYPE *restrict aym   = &A[i][j-1][1];

          k = 1;
          while (k < _PB_N-1) {
            size_t vl = __riscv_vsetvl_e32m4((size_t)(_PB_N - 1 - k));
            size_t off = (size_t)(k - 1);

