static
void kernel_jacobi_1d(int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_1D(A,N,n),
			    DATA_TYPE POLYBENCH_1D(B,N,n))
{
  int t, i;

#pragma scop
  for (t = 0; t < _PB_TSTEPS; t++) {
#if defined(__riscv_vector) && defined(DATA_TYPE_IS_DOUBLE)
    {
      const DATA_TYPE c = (DATA_TYPE)0.33333;
      i = 1;
      for (; i < _PB_N - 1; ) {
        size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - 1 - i));
        vfloat64m1_t va0 = __riscv_vle64_v_f64m1(&A[i - 1], vl);
        vfloat64m1_t va1 = __riscv_vle64_v_f64m1(&A[i], vl);
        vfloat64m1_t va2 = __riscv_vle64_v_f64m1(&A[i + 1], vl);
        vfloat64m1_t vs = __riscv_vfadd_vv_f64m1(va0, va1, vl);
        vs = __riscv_vfadd_vv_f64m1(vs, va2, vl);
        vs = __riscv_vfmul_vf_f64m1(vs, c, vl);
        __riscv_vse64_v_f64m1(&B[i], vs, vl);
        i += (int)vl;
      }

      i = 1;
      for (; i < _PB_N - 1; ) {
        size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - 1 - i));
        vfloat64m1_t vb0 = __riscv_vle64_v_f64m1(&B[i - 1], vl);
        vfloat64m1_t vb1 = __riscv_vle64_v_f64m1(&B[i], vl);
        vfloat64m1_t vb2 = __riscv_vle64_v_f64m1(&B[i + 1], vl);
        vfloat64m1_t vs = __riscv_vfadd_vv_f64m1(vb0, vb1, vl);
        vs = __riscv_vfadd_vv_f64m1(vs, vb2, vl);
        vs = __riscv_vfmul_vf_f64m1(vs, c, vl);
        __riscv_vse64_v_f64m1(&A[i], vs, vl);
        i += (int)vl;
      }
    }
#elif defined(__riscv_vector) && defined(DATA_TYPE_IS_FLOAT)
    {
      const float c = 0.33333f;
      i = 1;
      for (; i < _PB_N - 1; ) {
        size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_N - 1 - i));
        vfloat32m1_t va0 = __riscv_vle32_v_f32m1(&A[i - 1], vl);
        vfloat32m1_t va1 = __riscv_vle32_v_f32m1(&A[i], vl);
        vfloat32m1_t va2 = __riscv_vle32_v_f32m1(&A[i + 1], vl);
        vfloat32m1_t vs = __riscv_vfadd_vv_f32m1(va0, va1, vl);
        vs = __riscv_vfadd_vv_f32m1(vs, va2, vl);
        vs = __riscv_vfmul_vf_f32m1(vs, c, vl);
        __riscv_vse32_v_f32m1(&B[i], vs, vl);
        i += (int)vl;
      }

      i = 1;
      for (; i < _PB_N - 1; ) {
        size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_N - 1 - i));
        vfloat32m1_t vb0 = __riscv_vle32_v_f32m1(&B[i - 1], vl);
        vfloat32m1_t vb1 = __riscv_vle32_v_f32m1(&B[i], vl);
        vfloat32m1_t vb2 = __riscv_vle32_v_f32m1(&B[i + 1], vl);
        vfloat32m1_t vs = __riscv_vfadd_vv_f32m1(vb0, vb1, vl);
