        __riscv_vse32_v_f32m1(&A[i], vs, vl);
        i += (int)vl;
      }
    }
#else
    for (i = 1; i < _PB_N - 1; i++)
      B[i] = (DATA_TYPE)0.33333 * (A[i-1] + A[i] + A[i + 1]);
    for (i = 1; i < _PB_N - 1; i++)
