static
void kernel_jacobi_2d(int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
			    DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  int t, i, j;

#pragma scop
  for (t = 0; t < _PB_TSTEPS; t++)
  {
    for (i = 1; i < _PB_N - 1; i++)
    {
      DATA_TYPE *Ai   = &A[i][0];
      DATA_TYPE *Aim1 = &A[i - 1][0];
      DATA_TYPE *Aip1 = &A[i + 1][0];
      DATA_TYPE *Bi   = &B[i][0];

