      j = 1;
      for (; j < _PB_N - 1; )
      {
        size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - 1 - j));
        vfloat64m1_t vc  = __riscv_vle64_v_f64m1((const double *)(Ai   + j), vl);
        vfloat64m1_t vlft= __riscv_vle64_v_f64m1((const double *)(Ai   + j - 1), vl);
        vfloat64m1_t vrgt= __riscv_vle64_v_f64m1((const double *)(Ai   + j + 1), vl);
        vfloat64m1_t vup = __riscv_vle64_v_f64m1((const double *)(Aim1 + j), vl);
