        vfloat64m1_t vup = __riscv_vle64_v_f64m1((const double *)(Bim1 + j), vl);
        vfloat64m1_t vdn = __riscv_vle64_v_f64m1((const double *)(Bip1 + j), vl);

        vfloat64m1_t vsum = __riscv_vfadd_vv_f64m1(vc, vlft, vl);
        vsum = __riscv_vfadd_vv_f64m1(vsum, vrgt, vl);
        vsum = __riscv_vfadd_vv_f64m1(vsum, vup, vl);
        vsum = __riscv_vfadd_vv_f64m1(vsum, vdn, vl);
        vsum = __riscv_vfmul_vf_f64m1(vsum, (double)0.2, vl);

        __riscv_vse64_v_f64m1((double *)(Ai + j), vsum, vl);
        j += (int)vl;
      }
#else
      for (j = 1; j < _PB_N - 1; j++)
        Ai[j] = SCALAR_VAL(0.2) * (Bi[j] + Bi[j-1] + Bi[j+1] + Bip1[j] + Bim1[j]);
