static
void kernel_lu(int n,
	       DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *Ai = A[i];

    for (j = 0; j < i; j++) {
      DATA_TYPE sum = Ai[j];

#if defined(__riscv_vector) && defined(DATA_TYPE_IS_DOUBLE)
      if (j >= 4) {
        size_t vl;
        DATA_TYPE vacc = (DATA_TYPE)0;
        k = 0;
        for (; k < j; k += (int)vl) {
          vfloat64m1_t vzero, vred, vik, vkj, vmul;
          vl = __riscv_vsetvl_e64m1((size_t)(j - k));
          vik = __riscv_vle64_v_f64m1(&Ai[k], vl);
          vkj = __riscv_vlse64_v_f64m1(&A[k][j], (ptrdiff_t)(n * sizeof(DATA_TYPE)), vl);
          vmul = __riscv_vfmul_vv_f64m1(vik, vkj, vl);
          vzero = __riscv_vfmv_v_f_f64m1((DATA_TYPE)0, 1);
          vred = __riscv_vfredusum_vs_f64m1_f64m1(vmul, vzero, vl);
          vacc += __riscv_vfmv_f_s_f64m1_f64(vred);
        }
        sum -= vacc;
      } else
#elif defined(__riscv_vector) && defined(DATA_TYPE_IS_FLOAT)
      if (j >= 8) {
        size_t vl;
        DATA_TYPE vacc = (DATA_TYPE)0;
        k = 0;
        for (; k < j; k += (int)vl) {
          vfloat32m1_t vzero, vred, vik, vkj, vmul;
          vl = __riscv_vsetvl_e32m1((size_t)(j - k));
          vik = __riscv_vle32_v_f32m1(&Ai[k], vl);
          vkj = __riscv_vlse32_v_f32m1(&A[k][j], (ptrdiff_t)(n * sizeof(DATA_TYPE)), vl);
          vmul = __riscv_vfmul_vv_f32m1(vik, vkj, vl);
          vzero = __riscv_vfmv_v_f_f32m1((DATA_TYPE)0, 1);
          vred = __riscv_vfredusum_vs_f32m1_f32m1(vmul, vzero, vl);
          vacc += __riscv_vfmv_f_s_f32m1_f32(vred);
        }
        sum -= vacc;
      } else
#endif
      {
        for (k = 0; k < j; k++) {
          sum -= Ai[k] * A[k][j];
        }
      }

      Ai[j] = sum / A[j][j];
    }

    for (j = i; j < _PB_N; j++) {
      DATA_TYPE sum = Ai[j];

#if defined(__riscv_vector) && defined(DATA_TYPE_IS_DOUBLE)
      if (i >= 4) {
        size_t vl;
        DATA_TYPE vacc = (DATA_TYPE)0;
        k = 0;
        for (; k < i; k += (int)vl) {
          vfloat64m1_t vzero, vred, vik, vkj, vmul;
          vl = __riscv_vsetvl_e64m1((size_t)(i - k));
          vik = __riscv_vle64_v_f64m1(&Ai[k], vl);
          vkj = __riscv_vlse64_v_f64m1(&A[k][j], (ptrdiff_t)(n * sizeof(DATA_TYPE)), vl);
          vmul = __riscv_vfmul_vv_f64m1(vik, vkj, vl);
          vzero = __riscv_vfmv_v_f_f64m1((DATA_TYPE)0, 1);
          vred = __riscv_vfredusum_vs_f64m1_f64m1(vmul, vzero, vl);
          vacc += __riscv_vfmv_f_s_f64m1_f64(vred);
        }
        sum -= vacc;
      } else
#elif defined(__riscv_vector) && defined(DATA_TYPE_IS_FLOAT)
      if (i >= 8) {
        size_t vl;
        DATA_TYPE vacc = (DATA_TYPE)0;
        k = 0;
        for (; k < i; k += (int)vl) {
          vfloat32m1_t vzero, vred, vik, vkj, vmul;
          vl = __riscv_vsetvl_e32m1((size_t)(i - k));
          vik = __riscv_vle32_v_f32m1(&Ai[k], vl);
          vkj = __riscv_vlse32_v_f32m1(&A[k][j], (ptrdiff_t)(n * sizeof(DATA_TYPE)), vl);
          vmul = __riscv_vfmul_vv_f32m1(vik, vkj, vl);
          vzero = __riscv_vfmv_v_f_f32m1((DATA_TYPE)0, 1);
          vred = __riscv_vfredusum_vs_f32m1_f32m1(vmul, vzero, vl);
          vacc += __riscv_vfmv_f_s_f32m1_f32(vred);
        }
        sum -= vacc;
      } else
#endif
      {
        for (k = 0; k < i; k++) {
          sum -= Ai[k] * A[k][j];
        }
      }

      Ai[j] = sum;
    }
  }
#pragma endscop
