		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j, k;
  DATA_TYPE w;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *Ai = A[i];

    for (j = 0; j < i; j++) {
      w = Ai[j];
      for (k = 0; k < j; k++) {
        w -= Ai[k] * A[k][j];
      }
      Ai[j] = w / A[j][j];
    }

    for (j = i; j < _PB_N; j++) {
      w = Ai[j];
#if defined(__riscv_vector)
      {
        int kk = 0;
        DATA_TYPE sum = (DATA_TYPE)0;
        while (kk < i) {
#if defined(DATA_TYPE_IS_DOUBLE)
          size_t vl = __riscv_vsetvl_e64m1((size_t)(i - kk));
          vfloat64m1_t va = __riscv_vle64_v_f64m1(&Ai[kk], vl);
          vfloat64m1_t vb = __riscv_vlse64_v_f64m1(&A[kk][j], (ptrdiff_t)(sizeof(A[0][0]) * n), vl);
          vfloat64m1_t vm = __riscv_vfmul_vv_f64m1(va, vb, vl);
          vfloat64m1_t vzero = __riscv_vfmv_v_f_f64m1((double)0.0, vl);
          vfloat64m1_t vred = __riscv_vfredusum_vs_f64m1_f64m1(vm, vzero, vl);
          sum += __riscv_vfmv_f_s_f64m1_f64(vred);
#elif defined(DATA_TYPE_IS_FLOAT)
          size_t vl = __riscv_vsetvl_e32m1((size_t)(i - kk));
          vfloat32m1_t va = __riscv_vle32_v_f32m1(&Ai[kk], vl);
          vfloat32m1_t vb = __riscv_vlse32_v_f32m1(&A[kk][j], (ptrdiff_t)(sizeof(A[0][0]) * n), vl);
          vfloat32m1_t vm = __riscv_vfmul_vv_f32m1(va, vb, vl);
          vfloat32m1_t vzero = __riscv_vfmv_v_f_f32m1((float)0.0f, vl);
          vfloat32m1_t vred = __riscv_vfredusum_vs_f32m1_f32m1(vm, vzero, vl);
          sum += __riscv_vfmv_f_s_f32m1_f32(vred);
#else
          for (; kk < i; kk++)
            sum += Ai[kk] * A[kk][j];
          break;
#endif
          kk += (int)vl;
        }
        w -= sum;
      }
#else
      for (k = 0; k < i; k++) {
        w -= Ai[k] * A[k][j];
      }
#endif
      Ai[j] = w;
    }
  }

  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *Ai = A[i];
    w = b[i];
#if defined(__riscv_vector)
    {
      int jj = 0;
      DATA_TYPE sum = (DATA_TYPE)0;
      while (jj < i) {
#if defined(DATA_TYPE_IS_DOUBLE)
        size_t vl = __riscv_vsetvl_e64m1((size_t)(i - jj));
        vfloat64m1_t va = __riscv_vle64_v_f64m1(&Ai[jj], vl);
        vfloat64m1_t vb = __riscv_vle64_v_f64m1(&y[jj], vl);
        vfloat64m1_t vm = __riscv_vfmul_vv_f64m1(va, vb, vl);
        vfloat64m1_t vzero = __riscv_vfmv_v_f_f64m1((double)0.0, vl);
        vfloat64m1_t vred = __riscv_vfredusum_vs_f64m1_f64m1(vm, vzero, vl);
        sum += __riscv_vfmv_f_s_f64m1_f64(vred);
#elif defined(DATA_TYPE_IS_FLOAT)
        size_t vl = __riscv_vsetvl_e32m1((size_t)(i - jj));
        vfloat32m1_t va = __riscv_vle32_v_f32m1(&Ai[jj], vl);
        vfloat32m1_t vb = __riscv_vle32_v_f32m1(&y[jj], vl);
        vfloat32m1_t vm = __riscv_vfmul_vv_f32m1(va, vb, vl);
        vfloat32m1_t vzero = __riscv_vfmv_v_f_f32m1((float)0.0f, vl);
        vfloat32m1_t vred = __riscv_vfredusum_vs_f32m1_f32m1(vm, vzero, vl);
        sum += __riscv_vfmv_f_s_f32m1_f32(vred);
#else
        for (; jj < i; jj++)
          sum += Ai[jj] * y[jj];
        break;
#endif
        jj += (int)vl;
      }
      w -= sum;
    }
#else
    for (j = 0; j < i; j++)
      w -= Ai[j] * y[j];
#endif
    y[i] = w;
  }

  for (i = _PB_N - 1; i >= 0; i--) {
    DATA_TYPE *Ai = A[i];
    w = y[i];
#if defined(__riscv_vector)
    {
      int jj = i + 1;
      DATA_TYPE sum = (DATA_TYPE)0;
      while (jj < _PB_N) {
#if defined(DATA_TYPE_IS_DOUBLE)
        size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - jj));
        vfloat64m1_t va = __riscv_vle64_v_f64m1(&Ai[jj], vl);
        vfloat64m1_t vb = __riscv_vle64_v_f64m1(&x[jj], vl);
        vfloat64m1_t vm = __riscv_vfmul_vv_f64m1(va, vb, vl);
        vfloat64m1_t vzero = __riscv_vfmv_v_f_f64m1((double)0.0, vl);
        vfloat64m1_t vred = __riscv_vfredusum_vs_f64m1_f64m1(vm, vzero, vl);
        sum += __riscv_vfmv_f_s_f64m1_f64(vred);
#elif defined(DATA_TYPE_IS_FLOAT)
        size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_N - jj));
        vfloat32m1_t va = __riscv_vle32_v_f32m1(&Ai[jj], vl);
        vfloat32m1_t vb = __riscv_vle32_v_f32m1(&x[jj], vl);
        vfloat32m1_t vm = __riscv_vfmul_vv_f32m1(va, vb, vl);
        vfloat32m1_t vzero = __riscv_vfmv_v_f_f32m1((float)0.0f, vl);
        vfloat32m1_t vred = __riscv_vfredusum_vs_f32m1_f32m1(vm, vzero, vl);
        sum += __riscv_vfmv_f_s_f32m1_f32(vred);
#else
        for (; jj < _PB_N; jj++)
          sum += Ai[jj] * x[jj];
        break;
#endif
        jj += (int)vl;
      }
      w -= sum;
    }
#else
    for (j = i + 1; j < _PB_N; j++)
      w -= Ai[j] * x[j];
#endif
    x[i] = w / Ai[i];
  }
#pragma endscop
}

