static
void kernel_mvt(int n,
		DATA_TYPE POLYBENCH_1D(x1,N,n),
		DATA_TYPE POLYBENCH_1D(x2,N,n),
		DATA_TYPE POLYBENCH_1D(y_1,N,n),
		DATA_TYPE POLYBENCH_1D(y_2,N,n),
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE acc1 = x1[i];
    DATA_TYPE *Ai = &A[i][0];

#if defined(__riscv_vector) && defined(DATA_TYPE_IS_FLOAT)
    j = 0;
    {
      size_t avl = (size_t)_PB_N;
      while (avl > 0) {
        size_t vl = __riscv_vsetvl_e32m1(avl);
        vfloat32m1_t vA = __riscv_vle32_v_f32m1((const float *)&Ai[j], vl);
        vfloat32m1_t vy = __riscv_vle32_v_f32m1((const float *)&y_1[j], vl);
        vfloat32m1_t vprod = __riscv_vfmul_vv_f32m1(vA, vy, vl);
        vfloat32m1_t vzero = __riscv_vfmv_v_f_f32m1(0.0f, vl);
        acc1 += (DATA_TYPE)__riscv_vfmv_f_s_f32m1_f32(
            __riscv_vfredusum_vs_f32m1_f32m1(vprod, vzero, vzero, vl));
        j += (int)vl;
        avl -= vl;
      }
    }
#elif defined(__riscv_vector) && defined(DATA_TYPE_IS_DOUBLE)
    j = 0;
    {
      size_t avl = (size_t)_PB_N;
      while (avl > 0) {
        size_t vl = __riscv_vsetvl_e64m1(avl);
        vfloat64m1_t vA = __riscv_vle64_v_f64m1((const double *)&Ai[j], vl);
        vfloat64m1_t vy = __riscv_vle64_v_f64m1((const double *)&y_1[j], vl);
        vfloat64m1_t vprod = __riscv_vfmul_vv_f64m1(vA, vy, vl);
        vfloat64m1_t vzero = __riscv_vfmv_v_f_f64m1(0.0, vl);
        acc1 += (DATA_TYPE)__riscv_vfmv_f_s_f64m1_f64(
            __riscv_vfredusum_vs_f64m1_f64m1(vprod, vzero, vzero, vl));
        j += (int)vl;
        avl -= vl;
      }
    }
#else
    for (j = 0; j < _PB_N; j++)
      acc1 = acc1 + Ai[j] * y_1[j];
#endif

    x1[i] = acc1;
  }

  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE acc2 = x2[i];

#if defined(__riscv_vector) && defined(DATA_TYPE_IS_FLOAT)
    j = 0;
    {
      size_t avl = (size_t)_PB_N;
      while (avl > 0) {
        size_t vl = __riscv_vsetvl_e32m1(avl);
        float tmpA[vl];
        size_t k;
        for (k = 0; k < vl; k++)
          tmpA[k] = (float)A[j + (int)k][i];

        vfloat32m1_t vA = __riscv_vle32_v_f32m1(tmpA, vl);
        vfloat32m1_t vy = __riscv_vle32_v_f32m1((const float *)&y_2[j], vl);
        vfloat32m1_t vprod = __riscv_vfmul_vv_f32m1(vA, vy, vl);
        vfloat32m1_t vzero = __riscv_vfmv_v_f_f32m1(0.0f, vl);
        acc2 += (DATA_TYPE)__riscv_vfmv_f_s_f32m1_f32(
            __riscv_vfredusum_vs_f32m1_f32m1(vprod, vzero, vzero, vl));
        j += (int)vl;
        avl -= vl;
      }
    }
#elif defined(__riscv_vector) && defined(DATA_TYPE_IS_DOUBLE)
    j = 0;
    {
      size_t avl = (size_t)_PB_N;
      while (avl > 0) {
        size_t vl = __riscv_vsetvl_e64m1(avl);
        double tmpA[vl];
        size_t k;
        for (k = 0; k < vl; k++)
          tmpA[k] = (double)A[j + (int)k][i];

        vfloat64m1_t vA = __riscv_vle64_v_f64m1(tmpA, vl);
        vfloat64m1_t vy = __riscv_vle64_v_f64m1((const double *)&y_2[j], vl);
        vfloat64m1_t vprod = __riscv_vfmul_vv_f64m1(vA, vy, vl);
        vfloat64m1_t vzero = __riscv_vfmv_v_f_f64m1(0.0, vl);
        acc2 += (DATA_TYPE)__riscv_vfmv_f_s_f64m1_f64(
            __riscv_vfredusum_vs_f64m1_f64m1(vprod, vzero, vzero, vl));
        j += (int)vl;
        avl -= vl;
      }
    }
#else
    for (j = 0; j < _PB_N; j++)
      acc2 = acc2 + A[j][i] * y_2[j];
#endif

    x2[i] = acc2;
  }
#pragma endscop
}

