static
void kernel_nussinov(int n, base POLYBENCH_1D(seq,N,n),
			   DATA_TYPE POLYBENCH_2D(table,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (i = _PB_N - 1; i >= 0; --i) {
    DATA_TYPE * __restrict table_i = table[i];
    DATA_TYPE * __restrict table_ip1 = table[i + 1];
    base seq_i = seq[i];

    for (j = i + 1; j < _PB_N; ++j) {
      DATA_TYPE best = table_i[j];
      DATA_TYPE left = table_i[j - 1];
      DATA_TYPE down = table_ip1[j];
      DATA_TYPE diag = table_ip1[j - 1];

      best = max_score(best, left);
      best = max_score(best, down);

      if (i < j - 1)
        best = max_score(best, diag + match(seq_i, seq[j]));
      else
        best = max_score(best, diag);

#if defined(__GNUC__)
      __builtin_prefetch((const void *)&table_i[j + 8], 0, 1);
      __builtin_prefetch((const void *)&table_ip1[j + 8], 0, 1);
      if (i + 9 < _PB_N)
        __builtin_prefetch((const void *)&table[i + 9][j], 0, 0);
#endif

      for (k = i + 1; k < j; ++k) {
        DATA_TYPE cand = table_i[k] + table[k + 1][j];
        best = max_score(best, cand);
      }

      table_i[j] = best;
    }
  }
#pragma endscop

}

