static
void kernel_seidel_2d(int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int t, i, j;

#pragma scop
  for (t = 0; t <= _PB_TSTEPS - 1; t++) {
    for (i = 1; i <= _PB_N - 2; i++) {
      DATA_TYPE *rowm1 = &A[i - 1][0];
      DATA_TYPE *row0  = &A[i][0];
      DATA_TYPE *rowp1 = &A[i + 1][0];

#if defined(__riscv_vector) && defined(DATA_TYPE_IS_FLOAT)
      j = 1;
      while (j <= _PB_N - 2) {
        size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_N - 1 - j));

        vfloat32m1_t top_l = __riscv_vle32_v_f32m1(&rowm1[j - 1], vl);
        vfloat32m1_t top_c = __riscv_vle32_v_f32m1(&rowm1[j],     vl);
        vfloat32m1_t top_r = __riscv_vle32_v_f32m1(&rowm1[j + 1], vl);

        vfloat32m1_t mid_l = __riscv_vle32_v_f32m1(&row0[j - 1],  vl);
        vfloat32m1_t mid_c = __riscv_vle32_v_f32m1(&row0[j],      vl);
        vfloat32m1_t mid_r = __riscv_vle32_v_f32m1(&row0[j + 1],  vl);

        vfloat32m1_t bot_l = __riscv_vle32_v_f32m1(&rowp1[j - 1], vl);
        vfloat32m1_t bot_c = __riscv_vle32_v_f32m1(&rowp1[j],     vl);
        vfloat32m1_t bot_r = __riscv_vle32_v_f32m1(&rowp1[j + 1], vl);

        vfloat32m1_t s0 = __riscv_vfadd_vv_f32m1(top_l, top_c, vl);
        vfloat32m1_t s1 = __riscv_vfadd_vv_f32m1(top_r, mid_l, vl);
        vfloat32m1_t s2 = __riscv_vfadd_vv_f32m1(mid_c, mid_r, vl);
        vfloat32m1_t s3 = __riscv_vfadd_vv_f32m1(bot_l, bot_c, vl);

        s0 = __riscv_vfadd_vv_f32m1(s0, s1, vl);
        s2 = __riscv_vfadd_vv_f32m1(s2, s3, vl);
        s0 = __riscv_vfadd_vv_f32m1(s0, s2, vl);
        s0 = __riscv_vfadd_vv_f32m1(s0, bot_r, vl);

        s0 = __riscv_vfmul_vf_f32m1(s0, (float)(1.0f / 9.0f), vl);
        __riscv_vse32_v_f32m1(&row0[j], s0, vl);

        j += (int)vl;
      }

#elif defined(__riscv_vector) && defined(DATA_TYPE_IS_DOUBLE)
      j = 1;
      while (j <= _PB_N - 2) {
        size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - 1 - j));

        vfloat64m1_t top_l = __riscv_vle64_v_f64m1(&rowm1[j - 1], vl);
        vfloat64m1_t top_c = __riscv_vle64_v_f64m1(&rowm1[j],     vl);
        vfloat64m1_t top_r = __riscv_vle64_v_f64m1(&rowm1[j + 1], vl);

        vfloat64m1_t mid_l = __riscv_vle64_v_f64m1(&row0[j - 1],  vl);
        vfloat64m1_t mid_c = __riscv_vle64_v_f64m1(&row0[j],      vl);
        vfloat64m1_t mid_r = __riscv_vle64_v_f64m1(&row0[j + 1],  vl);

        vfloat64m1_t bot_l = __riscv_vle64_v_f64m1(&rowp1[j - 1], vl);
        vfloat64m1_t bot_c = __riscv_vle64_v_f64m1(&rowp1[j],     vl);
        vfloat64m1_t bot_r = __riscv_vle64_v_f64m1(&rowp1[j + 1], vl);

        vfloat64m1_t s0 = __riscv_vfadd_vv_f64m1(top_l, top_c, vl);
        vfloat64m1_t s1 = __riscv_vfadd_vv_f64m1(top_r, mid_l, vl);
        vfloat64m1_t s2 = __riscv_vfadd_vv_f64m1(mid_c, mid_r, vl);
        vfloat64m1_t s3 = __riscv_vfadd_vv_f64m1(bot_l, bot_c, vl);

        s0 = __riscv_vfadd_vv_f64m1(s0, s1, vl);
        s2 = __riscv_vfadd_vv_f64m1(s2, s3, vl);
        s0 = __riscv_vfadd_vv_f64m1(s0, s2, vl);
        s0 = __riscv_vfadd_vv_f64m1(s0, bot_r, vl);

        s0 = __riscv_vfmul_vf_f64m1(s0, (double)(1.0 / 9.0), vl);
        __riscv_vse64_v_f64m1(&row0[j], s0, vl);

        j += (int)vl;
      }

#else
      for (j = 1; j <= _PB_N - 2; j++) {
        row0[j] = (rowm1[j-1] + rowm1[j] + rowm1[j+1]
                 + row0 [j-1] + row0 [j] + row0 [j+1]
                 + rowp1[j-1] + rowp1[j] + rowp1[j+1]) / SCALAR_VAL(9.0);
      }
#endif
    }
  }
#pragma endscop
}

