static
void kernel_symm(int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;
  DATA_TYPE temp2;

#pragma scop
  for (i = 0; i < _PB_M; i++) {
    DATA_TYPE *Ai = &A[i][0];
    DATA_TYPE *Ci_row = &C[i][0];
    DATA_TYPE *Bi_row = &B[i][0];
    DATA_TYPE Aii = A[i][i];

    for (j = 0; j < _PB_N; j++) {
      DATA_TYPE Bij = Bi_row[j];
      DATA_TYPE alpha_Bij = alpha * Bij;
      temp2 = 0;

      for (k = 0; k < i; k++) {
        DATA_TYPE Aik = Ai[k];
        C[k][j] += alpha_Bij * Aik;
        temp2 += B[k][j] * Aik;
      }

      Ci_row[j] = beta * Ci_row[j] + alpha_Bij * Aii + alpha * temp2;
    }
  }
#pragma endscop
}

