static
void kernel_syr2k(int n, int m,
		  DATA_TYPE alpha,
		  DATA_TYPE beta,
		  DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		  DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		  DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *Ci = C[i];
    DATA_TYPE *Ai = A[i];

#if defined(__riscv_vector)
    if (sizeof(DATA_TYPE) == sizeof(float)) {
      size_t vl;
      int jj = 0;
      const float alphaf = (float)alpha;
      const float betaf = (float)beta;
      const float *Ai_f = (const float *)Ai;
      float *Ci_f = (float *)Ci;

      for (; jj <= i; jj += (int)vl) {
        vl = __riscv_vsetvl_e32m1((size_t)(i - jj + 1));
        vfloat32m1_t vc = __riscv_vle32_v_f32m1(&Ci_f[jj], vl);
        vc = __riscv_vfmul_vf_f32m1(vc, betaf, vl);
        __riscv_vse32_v_f32m1(&Ci_f[jj], vc, vl);
      }

      for (k = 0; k < _PB_M; k++) {
        const float bik = ((const float *)B[i])[k];
        const float aik = Ai_f[k];
        const float s1 = alphaf * bik;
        const float s2 = alphaf * aik;
        jj = 0;
        for (; jj <= i; jj += (int)vl) {
          vl = __riscv_vsetvl_e32m1((size_t)(i - jj + 1));
          vfloat32m1_t vc = __riscv_vle32_v_f32m1(&Ci_f[jj], vl);
          vfloat32m1_t va = __riscv_vle32_v_f32m1(&((const float *)A[jj])[k], vl);
          vfloat32m1_t vb = __riscv_vle32_v_f32m1(&((const float *)B[jj])[k], vl);

          vc = __riscv_vfmacc_vf_f32m1(vc, s1, va, vl);
          vc = __riscv_vfmacc_vf_f32m1(vc, s2, vb, vl);

          __riscv_vse32_v_f32m1(&Ci_f[jj], vc, vl);
        }
      }
    } else if (sizeof(DATA_TYPE) == sizeof(double)) {
      size_t vl;
      int jj = 0;
      const double alphad = (double)alpha;
      const double betad = (double)beta;
      const double *Ai_d = (const double *)Ai;
      double *Ci_d = (double *)Ci;

      for (; jj <= i; jj += (int)vl) {
        vl = __riscv_vsetvl_e64m1((size_t)(i - jj + 1));
        vfloat64m1_t vc = __riscv_vle64_v_f64m1(&Ci_d[jj], vl);
        vc = __riscv_vfmul_vf_f64m1(vc, betad, vl);
        __riscv_vse64_v_f64m1(&Ci_d[jj], vc, vl);
      }

      for (k = 0; k < _PB_M; k++) {
        const double bik = ((const double *)B[i])[k];
        const double aik = Ai_d[k];
        const double s1 = alphad * bik;
        const double s2 = alphad * aik;
        jj = 0;
        for (; jj <= i; jj += (int)vl) {
          vl = __riscv_vsetvl_e64m1((size_t)(i - jj + 1));
          vfloat64m1_t vc = __riscv_vle64_v_f64m1(&Ci_d[jj], vl);
          vfloat64m1_t va = __riscv_vle64_v_f64m1(&((const double *)A[jj])[k], vl);
          vfloat64m1_t vb = __riscv_vle64_v_f64m1(&((const double *)B[jj])[k], vl);

          vc = __riscv_vfmacc_vf_f64m1(vc, s1, va, vl);
          vc = __riscv_vfmacc_vf_f64m1(vc, s2, vb, vl);

          __riscv_vse64_v_f64m1(&Ci_d[jj], vc, vl);
