    } else
#endif
    {
      for (j = 0; j <= i; j++)
        Ci[j] *= beta;
      for (k = 0; k < _PB_M; k++) {
        DATA_TYPE aik = Ai[k];
        DATA_TYPE bik = B[i][k];
        DATA_TYPE s1 = alpha * bik;
        DATA_TYPE s2 = alpha * aik;
        for (j = 0; j <= i; j++) {
          Ci[j] += A[j][k] * s1 + B[j][k] * s2;
