static
void kernel_syrk(int n, int m,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *Ci = &C[i][0];

#if defined(__riscv_vector)
    int len = i + 1;
    int jj = 0;

    while (jj < len) {
      int rem = len - jj;
      size_t vl;
#if defined(DATA_TYPE_IS_DOUBLE)
      vl = __riscv_vsetvl_e64m4(rem);
      vfloat64m4_t vc = __riscv_vle64_v_f64m4(&Ci[jj], vl);
      vc = __riscv_vfmul_vf_f64m4(vc, beta, vl);
      __riscv_vse64_v_f64m4(&Ci[jj], vc, vl);
#elif defined(DATA_TYPE_IS_FLOAT)
      vl = __riscv_vsetvl_e32m4(rem);
      vfloat32m4_t vc = __riscv_vle32_v_f32m4(&Ci[jj], vl);
      vc = __riscv_vfmul_vf_f32m4(vc, beta, vl);
      __riscv_vse32_v_f32m4(&Ci[jj], vc, vl);
#else
      for (j = 0; j <= i; j++)
        Ci[j] *= beta;
      break;
#endif
      jj += (int)vl;
    }

    for (k = 0; k < _PB_M; k++) {
      DATA_TYPE aik_alpha = alpha * A[i][k];
      const DATA_TYPE *base = &A[0][k];
      jj = 0;

      while (jj < len) {
        int rem = len - jj;
        size_t vl;
#if defined(DATA_TYPE_IS_DOUBLE)
        vl = __riscv_vsetvl_e64m4(rem);
        vfloat64m4_t vc = __riscv_vle64_v_f64m4(&Ci[jj], vl);
        vfloat64m4_t va = __riscv_vlse64_v_f64m4(base + (ptrdiff_t)jj * m, (ptrdiff_t)(m * sizeof(DATA_TYPE)), vl);
        vc = __riscv_vfmacc_vf_f64m4(vc, aik_alpha, va, vl);
        __riscv_vse64_v_f64m4(&Ci[jj], vc, vl);
#elif defined(DATA_TYPE_IS_FLOAT)
        vl = __riscv_vsetvl_e32m4(rem);
        vfloat32m4_t vc = __riscv_vle32_v_f32m4(&Ci[jj], vl);
        vfloat32m4_t va = __riscv_vlse32_v_f32m4(base + (ptrdiff_t)jj * m, (ptrdiff_t)(m * sizeof(DATA_TYPE)), vl);
        vc = __riscv_vfmacc_vf_f32m4(vc, aik_alpha, va, vl);
        __riscv_vse32_v_f32m4(&Ci[jj], vc, vl);
#else
        for (j = 0; j <= i; j++)
          Ci[j] += aik_alpha * A[j][k];
        break;
#endif
        jj += (int)vl;
      }
    }
#else
    for (j = 0; j <= i; j++)
      C[i][j] *= beta;
    for (k = 0; k < _PB_M; k++) {
      DATA_TYPE aik_alpha = alpha * A[i][k];
      for (j = 0; j <= i; j++)
        C[i][j] += aik_alpha * A[j][k];
    }
#endif
  }
#pragma endscop

}

