static
void kernel_trisolv(int n,
		    DATA_TYPE POLYBENCH_2D(L,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(b,N,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE xi = b[i];
      DATA_TYPE *Li = &L[i][0];

#if defined(__riscv_vector) && defined(__riscv_flen) && (__riscv_flen >= 64)
      if (sizeof(DATA_TYPE) == sizeof(double))
        {
          double sum = 0.0;
          j = 0;
          while (j < i)
            {
              size_t vl = __riscv_vsetvl_e64m4((size_t)(i - j));
              vfloat64m4_t vL = __riscv_vle64_v_f64m4((const double *)&Li[j], vl);
              vfloat64m4_t vx = __riscv_vle64_v_f64m4((const double *)&x[j], vl);
              vfloat64m4_t vm = __riscv_vfmul_vv_f64m4(vL, vx, vl);
              vfloat64m1_t vred = __riscv_vfredusum_vs_f64m4_f64m1(
                  vm, __riscv_vfmv_v_f_f64m1(0.0, 1), vl);
              sum += __riscv_vfmv_f_s_f64m1_f64(vred);
              j += (int)vl;
            }
          xi -= (DATA_TYPE)sum;
        }
      else
#endif
#if defined(__riscv_vector) && defined(__riscv_flen) && (__riscv_flen >= 32)
      if (sizeof(DATA_TYPE) == sizeof(float))
        {
          float sum = 0.0f;
          j = 0;
          while (j < i)
            {
              size_t vl = __riscv_vsetvl_e32m8((size_t)(i - j));
              vfloat32m8_t vL = __riscv_vle32_v_f32m8((const float *)&Li[j], vl);
              vfloat32m8_t vx = __riscv_vle32_v_f32m8((const float *)&x[j], vl);
              vfloat32m8_t vm = __riscv_vfmul_vv_f32m8(vL, vx, vl);
              vfloat32m1_t vred = __riscv_vfredusum_vs_f32m8_f32m1(
                  vm, __riscv_vfmv_v_f_f32m1(0.0f, 1), vl);
              sum += __riscv_vfmv_f_s_f32m1_f32(vred);
              j += (int)vl;
            }
          xi -= (DATA_TYPE)sum;
        }
      else
#endif
        {
          for (j = 0; j < i; j++)
            xi -= Li[j] * x[j];
        }

      x[i] = xi / Li[i];
    }
#pragma endscop
}

