static
void kernel_trmm(int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_M; i++) {
#if defined(__riscv_vector) && defined(DATA_TYPE_IS_DOUBLE)
    j = 0;
    while (j < _PB_N) {
      size_t rem = (size_t)(_PB_N - j);

      if (rem >= 2) {
        size_t vl = __riscv_vsetvl_e64m4(rem >> 1);
        size_t step = vl << 1;

        vfloat64m4_t acc0 = __riscv_vle64_v_f64m4(&B[i][j], vl);
        vfloat64m4_t acc1 = __riscv_vle64_v_f64m4(&B[i][j + (int)vl], vl);

        for (k = i + 1; k < _PB_M; k++) {
          DATA_TYPE aik = A[k][i];
          vfloat64m4_t bk0 = __riscv_vle64_v_f64m4(&B[k][j], vl);
          vfloat64m4_t bk1 = __riscv_vle64_v_f64m4(&B[k][j + (int)vl], vl);
          acc0 = __riscv_vfmacc_vf_f64m4(acc0, aik, bk0, vl);
          acc1 = __riscv_vfmacc_vf_f64m4(acc1, aik, bk1, vl);
        }

        acc0 = __riscv_vfmul_vf_f64m4(acc0, alpha, vl);
        acc1 = __riscv_vfmul_vf_f64m4(acc1, alpha, vl);
        __riscv_vse64_v_f64m4(&B[i][j], acc0, vl);
        __riscv_vse64_v_f64m4(&B[i][j + (int)vl], acc1, vl);
        j += (int)step;
      } else {
        size_t vl = __riscv_vsetvl_e64m4(rem);
        vfloat64m4_t acc0 = __riscv_vle64_v_f64m4(&B[i][j], vl);

        for (k = i + 1; k < _PB_M; k++) {
          vfloat64m4_t bk0 = __riscv_vle64_v_f64m4(&B[k][j], vl);
          acc0 = __riscv_vfmacc_vf_f64m4(acc0, A[k][i], bk0, vl);
        }

        acc0 = __riscv_vfmul_vf_f64m4(acc0, alpha, vl);
        __riscv_vse64_v_f64m4(&B[i][j], acc0, vl);
        j += (int)vl;
      }
    }

#elif defined(__riscv_vector) && defined(DATA_TYPE_IS_FLOAT)
    j = 0;
    while (j < _PB_N) {
      size_t rem = (size_t)(_PB_N - j);

      if (rem >= 2) {
        size_t vl = __riscv_vsetvl_e32m4(rem >> 1);
        size_t step = vl << 1;

        vfloat32m4_t acc0 = __riscv_vle32_v_f32m4(&B[i][j], vl);
        vfloat32m4_t acc1 = __riscv_vle32_v_f32m4(&B[i][j + (int)vl], vl);

        for (k = i + 1; k < _PB_M; k++) {
          DATA_TYPE aik = A[k][i];
          vfloat32m4_t bk0 = __riscv_vle32_v_f32m4(&B[k][j], vl);
          vfloat32m4_t bk1 = __riscv_vle32_v_f32m4(&B[k][j + (int)vl], vl);
          acc0 = __riscv_vfmacc_vf_f32m4(acc0, aik, bk0, vl);
          acc1 = __riscv_vfmacc_vf_f32m4(acc1, aik, bk1, vl);
        }

        acc0 = __riscv_vfmul_vf_f32m4(acc0, alpha, vl);
        acc1 = __riscv_vfmul_vf_f32m4(acc1, alpha, vl);
        __riscv_vse32_v_f32m4(&B[i][j], acc0, vl);
        __riscv_vse32_v_f32m4(&B[i][j + (int)vl], acc1, vl);
        j += (int)step;
      } else {
        size_t vl = __riscv_vsetvl_e32m4(rem);
        vfloat32m4_t acc0 = __riscv_vle32_v_f32m4(&B[i][j], vl);

        for (k = i + 1; k < _PB_M; k++) {
          vfloat32m4_t bk0 = __riscv_vle32_v_f32m4(&B[k][j], vl);
          acc0 = __riscv_vfmacc_vf_f32m4(acc0, A[k][i], bk0, vl);
        }

        acc0 = __riscv_vfmul_vf_f32m4(acc0, alpha, vl);
        __riscv_vse32_v_f32m4(&B[i][j], acc0, vl);
        j += (int)vl;
      }
    }

#else
    for (j = 0; j < _PB_N; j++) {
      DATA_TYPE sum = B[i][j];
      for (k = i + 1; k < _PB_M; k++)
        sum += A[k][i] * B[k][j];
      B[i][j] = alpha * sum;
    }
#endif
  }
#pragma endscop

